_BUNDLE = {'common/metrics.py': '"""PanCollection RR/FR metrics, following DLPan-Toolbox definitions.\n\nFR PAN resizing uses scikit-image\'s antialiased bicubic approximation to\nMATLAB imresize; D_s/QNR must be parity-checked before a strict paper claim.\n"""\n\nimport numpy as np\nfrom scipy.ndimage import convolve, convolve1d\nfrom skimage.transform import resize\n\n\ndef _chw(image):\n    array = np.asarray(image, dtype=np.float64)\n    if array.ndim != 3 or not np.isfinite(array).all():\n        raise ValueError("Expected finite CHW image")\n    return array\n\n\ndef _onion(a, b):\n    """Cayley-Dickson multiplication used by MATLAB onions_quality."""\n    n = a.shape[-1]\n    if n == 1:\n        return a * b\n    half = n // 2\n    x, y = a[..., :half], a[..., half:]\n    z, w = b[..., :half], b[..., half:]\n    cy = np.concatenate((y[..., :1], -y[..., 1:]), axis=-1)\n    cw = np.concatenate((w[..., :1], -w[..., 1:]), axis=-1)\n    if n == 2:\n        return np.concatenate((x * z - w * y, x * w + z * y), axis=-1)\n    cx = np.concatenate((x[..., :1], -x[..., 1:]), axis=-1)\n    return np.concatenate((_onion(x, z) - _onion(w, cy), _onion(cx, w) + _onion(z, y)), axis=-1)\n\n\ndef q2n(reference, fused, block=32):\n    """Q4/Q8 with nonoverlapping 32-pixel blocks, matching q2n.m here."""\n    reference, fused = _chw(reference), _chw(fused)\n    if reference.shape != fused.shape:\n        raise ValueError("Q2n shapes differ")\n    channels, height, width = reference.shape\n    if height % block or width % block or channels & (channels - 1):\n        raise ValueError("Q2n requires block-aligned images and power-of-2 bands")\n    def blocks(image):\n        # MATLAB uint16 saturates/rounds values before the hypercomplex index.\n        image = np.rint(np.clip(image, 0, 65535)).transpose(1, 2, 0)\n        return image.reshape(height // block, block, width // block, block, channels).transpose(0, 2, 1, 3, 4).reshape(-1, block, block, channels)\n    a, b = blocks(reference), blocks(fused)\n    mean_a = a.mean(axis=(1, 2), keepdims=True)\n    std_a = a.std(axis=(1, 2), ddof=1, keepdims=True)\n    std_a = np.where(std_a == 0, np.finfo(float).eps, std_a)\n    a = (a - mean_a) / std_a + 1\n    b = (b - mean_a) / std_a + 1\n    b[..., 1:] *= -1\n    m1, m2 = a.mean(axis=(1, 2)), b.mean(axis=(1, 2))\n    m1_sq, m2_sq = np.sum(m1 * m1, axis=-1), np.sum(m2 * m2, axis=-1)\n    bias = np.divide(2 * np.sqrt(m1_sq * m2_sq), m1_sq + m2_sq,\n                     out=np.zeros_like(m1_sq), where=(m1_sq + m2_sq) != 0)\n    n = block * block\n    variance_term = n / (n - 1) * (\n        np.mean(np.sum(a * a + b * b, axis=-1), axis=(1, 2)) - m1_sq - m2_sq\n    )\n    quality = np.empty((len(a), channels), dtype=np.float64)\n    nonzero = np.abs(variance_term) > 1e-12\n    quality[~nonzero] = 0\n    quality[~nonzero, -1] = bias[~nonzero]\n    if np.any(nonzero):\n        product_mean = _onion(a[nonzero], b[nonzero]).mean(axis=(1, 2))\n        mean_product = _onion(m1[nonzero], m2[nonzero])\n        quality[nonzero] = (product_mean - mean_product) * (n / (n - 1) * bias[nonzero] * 2 / variance_term[nonzero])[:, None]\n    return float(np.linalg.norm(quality, axis=-1).mean())\n\n\ndef rr_metrics(reference, fused, *, ratio=4):\n    """Return per-image RR metrics, not an image-concatenated score."""\n    reference, fused = _chw(reference), _chw(fused)\n    if reference.shape != fused.shape:\n        raise ValueError("RR shapes differ")\n    diff = fused - reference\n    dot = np.sum(reference * fused, axis=0)\n    norms = np.linalg.norm(reference, axis=0) * np.linalg.norm(fused, axis=0)\n    valid = norms > 0\n    sam = float(np.degrees(np.arccos(np.clip(dot[valid] / norms[valid], -1, 1))).mean())\n    means = reference.mean(axis=(1, 2))\n    band_mse = np.mean(diff * diff, axis=(1, 2))\n    ergas = float(100 / ratio * np.sqrt(np.mean(band_mse / np.maximum(means * means, 1e-30))))\n    # MATLAB SCC: Sobel gradient magnitudes on a 1-pixel cropped image.\n    sobel = np.array([[1, 2, 1], [0, 0, 0], [-1, -2, -1]], dtype=float)\n    def gradients(image):\n        image = image[:, 1:-1, 1:-1]\n        gy = np.stack([convolve(band, sobel, mode="constant") for band in image])\n        gx = np.stack([convolve(band, sobel.T, mode="constant") for band in image])\n        return np.hypot(gx, gy)\n    a, b = gradients(reference), gradients(fused)\n    scc = float(np.sum(a * b) / np.sqrt(np.sum(a * a) * np.sum(b * b)))\n    # The paper does not specify its PSNR convention. Use the empirically\n    # closest documented choice: per-band PSNR at peak 2047, then average.\n    psnr = float(np.mean(10 * np.log10(2047 * 2047 / np.maximum(band_mse, 1e-30))))\n    return {"SAM": sam, "ERGAS": ergas, "PSNR": psnr,\n            "SCC": scc, "Q2n": q2n(reference, fused)}\n\n\ndef _block_uqi(a, b, block=32):\n    """Average MATLAB uqi over nonoverlapping blocks."""\n    height, width = a.shape\n    if a.shape != b.shape or height % block or width % block:\n        raise ValueError("UQI shapes are not block aligned")\n    def group(image):\n        return image.reshape(height // block, block, width // block, block).transpose(0, 2, 1, 3).reshape(-1, block * block)\n    x, y = group(a), group(b)\n    mx, my = x.mean(axis=1), y.mean(axis=1)\n    vx, vy = x.var(axis=1, ddof=1), y.var(axis=1, ddof=1)\n    cov = np.sum((x - mx[:, None]) * (y - my[:, None]), axis=1) / (x.shape[1] - 1)\n    denominator = (vx + vy) * (mx * mx + my * my)\n    quality = np.divide(4 * cov * mx * my, denominator,\n                        out=np.zeros_like(mx), where=np.abs(denominator) > 1e-30)\n    return float(quality.mean())\n\n\ndef _interp23tap(image, ratio=4):\n    coeff = 2 * np.array([.5, .305334091185, 0, -.072698593239, 0, .021809577942,\n                          0, -.005192756653, 0, .000807762146, 0, -.000060081482])\n    coeff = np.r_[coeff[:0:-1], coeff]\n    for stage in range(int(np.log2(ratio))):\n        up = np.zeros((image.shape[0] * 2, image.shape[1] * 2))\n        offset = 1 if stage == 0 else 0\n        up[offset::2, offset::2] = image\n        image = convolve1d(convolve1d(up, coeff, axis=0, mode="wrap"), coeff, axis=1, mode="wrap")\n    return image\n\n\ndef fr_metrics(fused, lms, ms, pan, *, ratio=4, block=32):\n    """Toolbox-style QNR; PAN antialias resize is not MATLAB-bit-exact."""\n    fused, lms, ms = _chw(fused), _chw(lms), _chw(ms)\n    pan = np.asarray(pan, dtype=np.float64).squeeze()\n    if fused.shape != lms.shape or pan.shape != fused.shape[1:] or ms.shape[1:] != (pan.shape[0] // ratio, pan.shape[1] // ratio):\n        raise ValueError("FR input shapes differ")\n    channels = fused.shape[0]\n    spectral = [abs(_block_uqi(fused[i], fused[j], block) - _block_uqi(lms[i], lms[j], block))\n                for i in range(channels) for j in range(i + 1, channels)]\n    down = resize(pan, ms.shape[1:], order=3, mode="reflect", anti_aliasing=True, preserve_range=True)\n    pan_filtered = _interp23tap(down, ratio)\n    spatial = [abs(_block_uqi(fused[i], pan, block) - _block_uqi(lms[i], pan_filtered, block))\n               for i in range(channels)]\n    d_lambda, d_s = float(np.mean(spectral)), float(np.mean(spatial))\n    return {"D_lambda": d_lambda, "D_s": d_s, "QNR": (1 - d_lambda) * (1 - d_s)}\n\n', 'common/model.py': '"""Minimal forward-path repair around the untouched official network.py.\n\nThe official forward(pan, lms) references an undefined `ms`. Its three\nspatial stages require PAN and interpolated LMS at full resolution, plus\nthe original MS at one-quarter resolution. This adapter supplies that input\nexplicitly and retains the original modules, parameter names and operations.\n"""\n\nimport importlib.util\nfrom pathlib import Path\n\nimport torch\nfrom torch import nn\n\n\nUPSTREAM_PATH = Path(__file__).resolve().parents[1] / "references/upstream/network.py"\n\n\ndef _upstream_model():\n    if not UPSTREAM_PATH.is_file():\n        raise FileNotFoundError(f"Initialize the official SSA-MRN submodule: {UPSTREAM_PATH}")\n    spec = importlib.util.spec_from_file_location("ssamrn_official_network", UPSTREAM_PATH)\n    module = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(module)\n    return module.PansharpeningNet\n\n\nclass DirectMLPReLU(nn.PReLU):\n    """Equivalent PReLU expression avoiding a DirectML batch backward error."""\n\n    def forward(self, input):\n        slope = self.weight.view(1, -1, 1, 1)\n        return torch.where(input > 0, input, slope * input)\n\n\nclass RestoredPansharpeningNet(_upstream_model()):\n    """Official layers with an explicit low-resolution MS input."""\n\n    def __init__(self, channels, ssai_dimension=4, guide_channels=1):\n        super().__init__(channels)\n        if guide_channels not in (1, 3):\n            raise ValueError("guide_channels must be 1 (PAN) or 3 (RGB)")\n        self.guide_channels = guide_channels\n        if guide_channels == 3:\n            self.conv1t1 = nn.Conv2d(3, 3, 3, padding=1)\n            self.cov2t64 = nn.Conv2d(channels + 6, 64, 3, padding=1)\n            for blocks in (self.SSA_blocks, self.SSA_blocks1, self.SSA_blocks2):\n                for block in blocks:\n                    block.conv1t6 = nn.Conv2d(3, 4, 3, padding=1)\n        if ssai_dimension < 1:\n            raise ValueError("ssai_dimension must be positive")\n        self.ssai_dimension = ssai_dimension\n        if ssai_dimension == 4:\n            return  # Preserve the published upstream architecture and existing checkpoints.\n\n        # The upstream code hard-codes K=4, while the paper specifies K=6.\n        # Resize only the layers used by the restored forward path; leave upstream untouched.\n        self.fixed = ssai_dimension\n        for blocks in (self.SSA_blocks, self.SSA_blocks1, self.SSA_blocks2):\n            for block in blocks:\n                block.fixed = ssai_dimension\n                block.conv1t6 = nn.Conv2d(guide_channels, ssai_dimension, 3, padding=1)\n                block.conv6t6 = nn.Conv2d(ssai_dimension, ssai_dimension, 3, padding=1)\n                block.conv7t6_3 = nn.Conv2d(channels + 1, ssai_dimension, 3, padding=1)\n        for name in ("conv48tnum1", "conv48tnum2", "conv48tnum3"):\n            setattr(self, name, nn.Conv2d(ssai_dimension * channels, channels, 3, padding=1))\n\n    def use_directml_prelu(self):\n        """Keep PReLU weights/checkpoints while using a DirectML-safe backward."""\n        for name, module in self.named_modules():\n            if not name or not isinstance(module, nn.PReLU):\n                continue\n            parent = self.get_submodule(name.rpartition(".")[0]) if "." in name else self\n            replacement = DirectMLPReLU(module.num_parameters)\n            with torch.no_grad():\n                replacement.weight.copy_(module.weight)\n            setattr(parent, name.rpartition(".")[2], replacement)\n\n    def _attend(self, pan, features, ms, blocks, fusion, activation):\n        outputs = []\n        for band in range(self.channels):\n            band_input = torch.cat([features, ms[:, band : band + 1]], dim=1)\n            outputs.append(blocks[band](pan, band_input))\n        return activation(fusion(torch.cat(outputs, dim=1)))\n\n    def forward(self, pan, lms, ms):\n        if pan.ndim != 4 or lms.ndim != 4 or ms.ndim != 4:\n            raise ValueError("Expected NCHW tensors for pan, lms, and ms")\n        n, channels, h, w = lms.shape\n        if channels != self.channels or h % 4 or w % 4 or min(h, w) < 4:\n            raise ValueError(f"Invalid LMS shape: {tuple(lms.shape)}")\n        if pan.shape != (n, self.guide_channels, h, w) or ms.shape != (n, channels, h // 4, w // 4):\n            raise ValueError("Expected guide at LMS resolution and MS at 1/4 resolution")\n\n        pan_down_up = self.upsample1(self.downsample1(pan))\n        pan_updown = self.prelu(self.conv1t1(pan_down_up))\n        features = torch.cat([lms, pan, pan_updown], dim=1)\n        features = self.backbone(self.cov2t64(features))\n        res = self.conv64t48(features) + lms\n\n        pan_ms = self._attend(pan, res, lms, self.SSA_blocks, self.conv48tnum1, self.prelu1)\n        res = res + pan_ms\n\n        res_half = self.downsample100(res)\n        ms_half = self.upsample100(ms)\n        pan_half = self.downsample100(pan)\n        pan_ms = self._attend(pan_half, res_half, ms_half, self.SSA_blocks1, self.conv48tnum2, self.prelu2)\n        res_half = res_half + pan_ms\n\n        res_quarter = self.downsample200(res_half)\n        pan_quarter = self.downsample2(pan)\n        pan_ms = self._attend(pan_quarter, res_quarter, ms, self.SSA_blocks2, self.conv48tnum3, self.prelu3)\n\n        output = self.conv2ctc1(torch.cat([ms, pan_ms], dim=1))\n        output = self.conv2ctc2(torch.cat([self.upsample101(output), res_half], dim=1))\n        output = self.conv2ctc3(torch.cat([self.upsample102(output), res], dim=1))\n        return output\n\n', 'normalization.py': '"""Shared MS-anchored affine transform; no learned parameters or GT statistics."""\nimport torch\nfrom torch import nn\nfrom common.model import RestoredPansharpeningNet\n\nclass Model(nn.Module):\n    def __init__(self, arm, std_floor=0.01):\n        super().__init__()\n        if arm not in (\'N0\', \'N1\') or std_floor <= 0:\n            raise ValueError(\'Invalid arm or standard deviation floor\')\n        self.core = RestoredPansharpeningNet(4, ssai_dimension=4)\n        self.arm = arm\n        self.std_floor = float(std_floor)\n\n    def statistics(self, ms):\n        # Population variance, jointly across bands and spatial pixels, per sample.\n        # Explicit FP32 statistics under FP16 autocast; never pool batch dimension.\n        with torch.autocast(device_type=ms.device.type, enabled=False):\n            x = ms.float()\n            var, mean = torch.var_mean(x, dim=(1, 2, 3), correction=0, keepdim=True)\n            scale = var.clamp_min(0).sqrt().clamp_min(self.std_floor)\n        return mean, scale\n\n    def forward(self, pan, lms, ms):\n        if self.arm == \'N0\':\n            return self.core(pan, lms, ms)\n        mean, scale = self.statistics(ms)\n        # The same one affine transform for PAN, LMS and all four MS bands.\n        with torch.autocast(device_type=ms.device.type, enabled=False):\n            inputs = tuple((x.float() - mean) / scale for x in (pan, lms, ms))\n        prediction = self.core(*inputs)\n        with torch.autocast(device_type=ms.device.type, enabled=False):\n            return prediction.float() * scale + mean\n', 'references/upstream/network.py': 'import torch\nimport torch.nn as nn\nimport torch.nn.functional as F\n\n\nclass ResBlock(nn.Module):\n    def __init__(self, in_channels):\n        super(ResBlock, self).__init__()\n        self.conv1 = nn.Conv2d(in_channels, in_channels, kernel_size=3, padding=1, bias=False)\n        self.bn1 = nn.BatchNorm2d(in_channels)\n        self.conv2 = nn.Conv2d(in_channels, in_channels, kernel_size=3, padding=1, bias=False)\n        self.bn2 = nn.BatchNorm2d(in_channels)\n\n    def forward(self, x):\n        residual = x\n        out = self.conv1(x)\n        out = F.relu(self.bn1(out))\n        out = self.conv2(out)\n        out = self.bn2(out)\n        out += residual\n        out = F.relu(out)\n        return out\n\n\nclass Resbackbone(nn.Module):\n    def __init__(self, in_channels):\n        super(Resbackbone, self).__init__()\n        channel = 64\n        self.conv1 = nn.Conv2d(in_channels=in_channels, out_channels=channel, kernel_size=3, padding=1, stride=1,\n                               bias=True)\n\n        self.res1 = ResBlock(channel)\n        self.res2 = ResBlock(channel)\n        self.res3 = ResBlock(channel)\n        self.res4 = ResBlock(channel)\n\n        self.backbone = nn.Sequential(\n            self.res1,\n            self.res2,\n            self.res3,\n            self.res4,\n\n        )\n        self.relu = nn.ReLU(inplace=True)\n        self.conv2 = nn.Conv2d(in_channels=channel, out_channels=1, stride=1, kernel_size=3, padding=1,\n                               bias=True)\n\n    def forward(self, x):\n        x = self.relu(self.conv1(x))\n        x = self.backbone(x)\n        x = self.conv2(x)\n        return x\n\n\nclass Resblock(nn.Module):\n    def __init__(self):\n        super(Resblock, self).__init__()\n\n        channel = 64\n\n        self.conv20 = nn.Conv2d(in_channels=channel, out_channels=channel, padding=1, kernel_size=3, stride=1,\n                                bias=True)\n        self.conv21 = nn.Conv2d(in_channels=channel, out_channels=channel, padding=1, kernel_size=3, stride=1,\n                                bias=True)\n        self.relu = nn.ReLU(\n            inplace=True) \n    def forward(self, x):\n        rs1 = self.relu(self.conv20(x))\n        rs2 = self.conv21(rs1)  \n        # print(f"rs2:{rs2.shape},x:{x.shape}")\n        rs = torch.add(x, rs2) \n        return rs\n\n\nclass SSA(nn.Module):\n    def __init__(self,channels):\n        super(SSA, self).__init__()\n\n        self.fixed  = 4\n\n\n        self.conv1t6 = nn.Conv2d(in_channels=1, out_channels=self.fixed , kernel_size=3, stride=1, padding=1,\n                                 bias=True)\n        self.conv6t12 = nn.Conv2d(in_channels=6, out_channels=12, kernel_size=3, stride=1, padding=1,\n                                  bias=True)\n        self.conv6t6 = nn.Conv2d(in_channels=self.fixed , out_channels=self.fixed , kernel_size=3, stride=1, padding=1,\n                                 bias=True)\n        self.relu = nn.ReLU()\n        self.conv7t6_3 = nn.Conv2d(in_channels=channels + 1, out_channels=self.fixed, kernel_size=3, stride=1,\n                                   padding=1, bias=True)\n\n    def forward(self, pan, ms_pro):  # ms_pro 6xhxw  pan 1xhxw\n        pan_guide = self.relu(self.conv1t6(pan))\n        pan_guide = self.conv6t6(pan_guide)  # 6*h*w\n        ms_pro = self.conv7t6_3(ms_pro)\n        # pan reshape -> 6xhw\n        # ms_pro reshape -> 6xhw  -> transpose > 6xwh\n        b, c, h, w = ms_pro.size()\n        pan_reshape = pan_guide.view(b, c, -1)  # 6xhw\n        ms_pro_transpose = ms_pro.permute(0, 1, 3, 2)\n        ms_pro_reshape = ms_pro_transpose.reshape(b, c, -1)  # 6xhw\n        # print(ms_pro_reshape.shape)\n        # ms使用了转置\n\n        # pan_matrix * ms_pro_matrix -> 6xhwxwh -> softmax ->6xhxw\n        pan_matrix = torch.mul(pan_reshape, ms_pro_reshape)  # b x c x hw x wh\n        # print(pan_matrix.shape)\n        pan_matrix = pan_matrix.view(b, c, h, w)\n        # print(pan_matrix.shape)\n        pan_matrix = pan_matrix.permute(0, 1, 3, 2)\n        pan_matrix = pan_matrix.contiguous().view(b, c, -1)\n       \n        pan_matrix = F.softmax(pan_matrix, dim=-1)\n        # print(pan_matrix.shape)\n\n        # transpose_R * ms_pro_matrix -> 6xhwxwh -> reshape -> output= 6xhxw\n        output = torch.mul(pan_reshape, pan_matrix)  # b x c x hw\n        output = output.contiguous().view(b, c, h, w)  # reshape to 6xhxw\n\n        # print(f"res{res.shape}")\n        return output\n\n\n\n\n\n\n\nclass PansharpeningNet(nn.Module):\n    def __init__(self, channels):\n        super(PansharpeningNet, self).__init__()\n\n        self.fixed = 4\n\n        # Downsampling and Upsampling layers\n        self.downsample1 = nn.Upsample(scale_factor=0.5, mode=\'bilinear\', align_corners=True)\n        self.downsample2 = nn.Upsample(scale_factor=0.25, mode=\'bilinear\', align_corners=True)\n        self.upsample1 = nn.Upsample(scale_factor=2, mode=\'bilinear\', align_corners=True)\n        self.upsample2 = nn.Upsample(scale_factor=4, mode=\'bilinear\', align_corners=True)\n        self.downsample200 = nn.Upsample(scale_factor=0.5, mode=\'bilinear\', align_corners=True)\n        # Feature extraction and fusion layers with individual names\n        self.prelu1 = nn.PReLU()\n        self.prelu2 = nn.PReLU()\n        self.prelu3 = nn.PReLU()\n\n        self.conv1t64 = nn.Conv2d(1, 64, kernel_size=3, padding=1)\n        self.conv64tnum = nn.Conv2d(64, channels, kernel_size=3, padding=1)\n        self.convnumt64 = nn.Conv2d(channels, 64, kernel_size=3, padding=1)\n\n        self.conv1t64_pan = nn.Conv2d(1, 64, kernel_size=3, padding=1)\n        self.conv64tnum_pan = nn.Conv2d(64, channels, kernel_size=3, padding=1)\n\n        self.convnum3tnum1 = nn.Conv2d(channels * 3, channels, kernel_size=3, padding=1)\n        self.convnum3tnum2 = nn.Conv2d(channels * 3, channels, kernel_size=3, padding=1)\n        self.convnum3tnum3 = nn.Conv2d(channels * 3, channels, kernel_size=3, padding=1)\n\n        self.conv48tnum1 = nn.Conv2d(in_channels=self.fixed * channels, out_channels=channels, kernel_size=3, stride=1,\n                                     padding=1, bias=True)\n        self.conv48tnum2 = nn.Conv2d(in_channels=self.fixed * channels, out_channels=channels, kernel_size=3, stride=1,\n                                     padding=1, bias=True)\n        self.conv48tnum3 = nn.Conv2d(in_channels=self.fixed * channels, out_channels=channels, kernel_size=3, stride=1,\n                                     padding=1, bias=True)\n\n        self.conv7t6_1 = nn.Conv2d(in_channels=channels + 1, out_channels=self.fixed, kernel_size=3, stride=1,\n                                   padding=1, bias=True)\n        self.conv7t6_2 = nn.Conv2d(in_channels=channels + 1, out_channels=self.fixed, kernel_size=3, stride=1,\n                                   padding=1, bias=True)\n        self.conv7t6_3 = nn.Conv2d(in_channels=channels + 1, out_channels=self.fixed, kernel_size=3, stride=1,\n                                   padding=1, bias=True)\n\n        self.conv2ctc1 = nn.Conv2d(in_channels=channels * 2, out_channels=channels, kernel_size=3, stride=1, padding=1,\n                                   bias=True)\n        self.conv2ctc2 = nn.Conv2d(in_channels=channels * 2, out_channels=channels, kernel_size=3, stride=1, padding=1,\n                                   bias=True)\n        self.conv2ctc3 = nn.Conv2d(in_channels=channels * 2, out_channels=channels, kernel_size=3, stride=1, padding=1,\n                                   bias=True)\n\n        self.SSA_blocks = nn.ModuleList([SSA(channels=channels) for _ in range(channels)])\n\n        self.SSA_blocks1 = nn.ModuleList([SSA(channels=channels) for _ in range(channels)])\n        self.SSA_blocks2 = nn.ModuleList([SSA(channels=channels) for _ in range(channels)])\n        self.conv1t1 = nn.Conv2d(in_channels=1, out_channels=1, kernel_size=3, stride=1, padding=1, bias=True)\n        self.cov2t64 = nn.Conv2d(in_channels=2 + channels, out_channels=64, kernel_size=3, stride=1, padding=1,\n                                 bias=True)\n\n        self.res1 = Resblock()\n        self.res2 = Resblock()\n        self.res3 = Resblock()\n        self.res4 = Resblock()\n\n        self.backbone = nn.Sequential(\n                self.res1,\n                self.res2,\n                self.res3,\n                self.res4,\n            )\n        self.conv64t48 = nn.Conv2d(in_channels=64, out_channels=channels, kernel_size=3, stride=1, padding=1, bias=True)\n        self.fixed = 4;\n\n        # Downsampling and Upsampling layers\n        self.downsample = nn.Upsample(scale_factor=0.5, mode=\'bilinear\', align_corners=True)\n        self.upsample = nn.Upsample(scale_factor=2, mode=\'bilinear\', align_corners=True)\n        self.downsample1 = nn.Upsample(scale_factor=0.25, mode=\'bilinear\', align_corners=True)\n        self.upsample1 = nn.Upsample(scale_factor=4, mode=\'bilinear\', align_corners=True)\n        self.upsample100 = nn.Upsample(scale_factor=2, mode=\'bilinear\', align_corners=True)\n        self.downsample100 = nn.Upsample(scale_factor=0.5, mode=\'bilinear\', align_corners=True)\n        self.upsample101  = nn.Upsample(scale_factor=2, mode=\'bilinear\', align_corners=True)\n        self.upsample102\\\n            = nn.Upsample(scale_factor=2, mode=\'bilinear\', align_corners=True)\n        # Fusion layers\n        self.resblock = Resblock()\n        self.prelu = nn.PReLU()\n        self.conv1t64 = nn.Conv2d(1, 64, kernel_size=3, padding=1)\n        self.conv64tnum = nn.Conv2d(64, channels, kernel_size=3, padding=1)\n        self.convnumt64 = nn.Conv2d(channels, 64, kernel_size=3, padding=1)\n\n        self.conv1t64bf2 = nn.Conv2d(1, 64, kernel_size=3, padding=1)\n        self.conv64tnumbf2 = nn.Conv2d(64, channels, kernel_size=3, padding=1)\n        self.convnumt64bf2 = nn.Conv2d(channels, 64, kernel_size=3, padding=1)\n\n        self.convnumtnum = nn.Conv2d(channels * 3, channels * 3, kernel_size=3, padding=1)\n        self.convctc1 = nn.Conv2d(channels, channels, kernel_size=3, padding=1)  # convctc1\n        self.convctc2 = nn.Conv2d(channels, channels, kernel_size=3, padding=1)  # convctc2\n        self.convnum3tnum = nn.Conv2d(channels * 3, channels, kernel_size=3, padding=1)\n        self.relu = nn.ReLU()\n\n        self.conv2 = nn.Conv2d(in_channels=channels, out_channels=channels * 6, stride=1, kernel_size=3, padding=1,\n                               bias=True)\n\n        self.SSA_blocks = nn.ModuleList(\n            [SSA(channels=channels) for _ in range(channels)])  # Adding multi-scale blocks\n\n        self.conv48tnum1 = nn.Conv2d(in_channels=self.fixed * channels, out_channels=channels, kernel_size=3, stride=1,\n                                     padding=1, bias=True)\n        self.conv48tnum2 = nn.Conv2d(in_channels=self.fixed * channels, out_channels=channels, kernel_size=3, stride=1,\n                                     padding=1, bias=True)\n\n        self.conv48t48_1 = nn.Conv2d(in_channels=6 * channels, out_channels=6 * channels, kernel_size=3, stride=1,\n                                     padding=1, bias=True)\n        self.conv48t48_2 = nn.Conv2d(in_channels=channels, out_channels=channels, kernel_size=3, stride=1, padding=1,\n                                     bias=True)\n        self.conv48t48_3 = nn.Conv2d(in_channels=6 * channels, out_channels=6 * channels, kernel_size=3, stride=1,\n                                     padding=1, bias=True)\n\n        self.conv7t6 = nn.Conv2d(in_channels=channels + 1, out_channels=self.fixed, kernel_size=3, stride=1, padding=1,\n                                 bias=True)\n\n        self.convnum3tn64 = nn.Conv2d(in_channels=channels * 3, out_channels=64, kernel_size=3, stride=1, padding=1,\n                                      bias=True)\n\n        self.group_size = 6 \n        self.channels = channels\n        self.cov2t64 = nn.Conv2d(in_channels=2 + channels, out_channels=64, kernel_size=3, stride=1, padding=1,\n                                 bias=True)\n        self.conv64t48 = nn.Conv2d(in_channels=64, out_channels=channels, kernel_size=3, stride=1, padding=1, bias=True)\n        self.conv1t1 = nn.Conv2d(in_channels=1, out_channels=1, kernel_size=3, stride=1, padding=1, bias=True)\n\n        self.convnumt48 = nn.Conv2d(in_channels=channels, out_channels=channels, kernel_size=3, stride=1, padding=1,\n                                    bias=True)\n\n        self.relu = nn.ReLU(inplace=True)\n        self.conv8t4 = nn.Conv2d(in_channels=8, out_channels=channels, kernel_size=3, stride=1, padding=1,\n                                    bias=True)\n\n\n\n   \n    def forward(self, pan, lms):\n        # Stage 1: Downsample and upsample each input\n        pan_down_up = self.upsample1(self.downsample1(pan))\n        pan_updown = self.prelu(self.conv1t1(pan_down_up))\n        input = torch.cat([lms, pan, pan_updown], dim=1)\n\n        y = self.cov2t64(input)\n        y = self.backbone(y)\n        y1 = self.conv64t48(y)\n        rs = y1 + lms\n\n        # Process input channels separately\n        split_input = [rs[:, i:i + self.group_size, :, :] for i in range(0, 48, self.group_size)]\n        split_ms = [lms[:, i, :, :].unsqueeze(1) for i in range(self.channels)]\n\n        outputs = []\n        for input_channel, ms_channel, ssa in zip(split_input, split_ms, self.SSA_blocks):\n            x = torch.cat([rs, ms_channel], dim=1)\n\n            ms_one = ssa(pan, x)\n            outputs.append(ms_one)\n\n        pan_ms = torch.cat(outputs, dim=1)\n        pan_ms = self.prelu1(self.conv48tnum1(pan_ms))\n        fsm_msb = rs + pan_ms\n        res = fsm_msb\n\n        res_down = self.downsample100(res)\n\n        # Stage 2: MS upsample and next stage fusion\n        ms_up = self.upsample100(ms)\n        rs = res_down\n\n        split_input = [rs[:, i:i + self.group_size, :, :] for i in range(0, 48, self.group_size)]\n        split_ms = [ms_up[:, i, :, :].unsqueeze(1) for i in range(self.channels)]\n\n        outputs = []\n        for input_channel, ms_channel, ssa in zip(split_input, split_ms, self.SSA_blocks1):\n            x = torch.cat([rs, ms_channel], dim=1)\n\n            pan_down = self.downsample100(pan)\n            ms_one = ssa(pan_down, x)\n            outputs.append(ms_one)\n\n        pan_ms = torch.cat(outputs, dim=1)\n        pan_ms = self.prelu2(self.conv48tnum2(pan_ms))\n        fsm_msb = rs + pan_ms\n        res_down = fsm_msb\n\n        # Stage 3: Small scale stage\n        res_small = self.downsample200(res_down)\n        rs = res_small\n\n        split_input = [rs[:, i:i + self.group_size, :, :] for i in range(0, 48, self.group_size)]\n        split_ms = [ms[:, i, :, :].unsqueeze(1) for i in range(self.channels)]\n\n        outputs = []\n        for input_channel, ms_channel, ssa in zip(split_input, split_ms, self.SSA_blocks2):\n            x = torch.cat([rs, ms_channel], dim=1)\n\n            pan_down = self.downsample2(pan)\n            ms_one = ssa(pan_down, x)\n            outputs.append(ms_one)\n\n        pan_ms = torch.cat(outputs, dim=1)\n        pan_ms = self.prelu3(self.conv48tnum3(pan_ms))\n        res_small = pan_ms\n\n        # Output processing\n        ms_output = ms\n        ms_output = torch.cat([ms_output, res_small], dim=1)\n        ms_output = self.conv2ctc1(ms_output)\n\n        ms_output = self.upsample101(ms_output)\n        ms_output = torch.cat([ms_output, res_down], dim=1)\n        ms_output = self.conv2ctc2(ms_output)\n\n        ms_output = self.upsample102(ms_output)\n        ms_output = torch.cat([ms_output, res], dim=1)\n        ms_output = self.conv2ctc3(ms_output)\n\n\n\n\n        return ms_output\n\n', 'worker.py': 'import os\nos.environ.setdefault(\'OMP_NUM_THREADS\',\'1\')\nos.environ.setdefault(\'MKL_NUM_THREADS\',\'1\')\nimport sys,json,time,math,hashlib,random,copy,signal,traceback,platform\nfrom pathlib import Path\nfrom datetime import datetime,timedelta,timezone\nimport numpy as np\nimport torch\nfrom torch import nn\nfrom torch.nn import functional as F\nimport h5py\nROOT=Path(__file__).parent\nsys.path.insert(0,str(ROOT))\nfrom normalization import Model\nfrom common.metrics import rr_metrics,fr_metrics\nKEYS=(\'pan\',\'lms\',\'ms\',\'gt\')\nKST=timezone(timedelta(hours=9))\n\ndef sha(p):\n    h=hashlib.sha256()\n    with open(p,\'rb\') as f:\n        for b in iter(lambda:f.read(8*1024**2),b\'\'):h.update(b)\n    return h.hexdigest()\n\ndef digest_state(sd):\n    h=hashlib.sha256()\n    for k,v in sorted(sd.items()):h.update(k.encode());h.update(v.detach().cpu().contiguous().numpy().tobytes())\n    return h.hexdigest()\n\ndef write(p,obj):\n    p=Path(p);p.parent.mkdir(parents=True,exist_ok=True)\n    t=p.with_suffix(p.suffix+\'.tmp\');t.write_text(json.dumps(obj,indent=2,allow_nan=False),encoding=\'utf8\');os.replace(t,p)\n\ndef cpu(obj):\n    if torch.is_tensor(obj):return obj.detach().cpu().clone()\n    if isinstance(obj,dict):return {k:cpu(v) for k,v in obj.items()}\n    if isinstance(obj,list):return [cpu(v) for v in obj]\n    if isinstance(obj,tuple):return tuple(cpu(v) for v in obj)\n    return obj\n\ndef atomic(p,obj):\n    p=Path(p);p.parent.mkdir(parents=True,exist_ok=True);t=p.with_suffix(\'.tmp\')\n    torch.save(cpu(obj),t)\n    with t.open(\'r+b\') as f:f.flush();os.fsync(f.fileno())\n    os.replace(t,p)\n\n\ndef read_arrays(path,gt=True):\n    with h5py.File(path,\'r\') as f:return {k:np.asarray(f[k],dtype=np.float32)/2047. for k in (KEYS if gt else KEYS[:3])}\n\ndef gpu_cache(path):\n    arrays=read_arrays(path)\n    required=sum(v.nbytes for v in arrays.values())\n    free,total=torch.cuda.mem_get_info()\n    if required>free*0.8:raise MemoryError(f\'GPU resident cache requires {required/2**30:.2f} GiB; free {free/2**30:.2f} GiB. No silent CPU fallback.\')\n    return {k:torch.from_numpy(a).cuda() for k,a in arrays.items()}\n\n@torch.inference_mode()\ndef validation(m,cache,micro):\n    m.eval();s=torch.zeros(3,device=\'cuda\',dtype=torch.float64)\n    pixels=torch.zeros((),device=\'cuda\',dtype=torch.int64);n=0;elements=0\n    for i in range(0,len(cache[\'pan\']),micro):\n        b=[cache[k][i:i+micro] for k in KEYS];gt=b[3]\n        p=m(*b[:3]).float()\n        if not torch.isfinite(p).all():raise FloatingPointError(\'Nonfinite validation prediction\')\n        error=(p-gt).square()\n        s[0]+=error.double().sum();elements+=gt.numel()\n        s[1]+=(-10*torch.log10(error.mean((2,3)).clamp_min(1e-15))).mean(1).double().sum();n+=len(gt)\n        norm=p.norm(dim=1)*gt.norm(dim=1);mask=norm>1e-12\n        cos=(p*gt).sum(1)/norm.clamp_min(1e-12)\n        s[2]+=torch.acos(cos.clamp(-1,1))[mask].double().sum();pixels+=mask.sum()\n    a=s.cpu().tolist()\n    return dict(val_mse=a[0]/elements,val_psnr=a[1]/n,val_sam=math.degrees(a[2]/max(int(pixels),1)))\n\n@torch.inference_mode()\ndef normalization_diagnostics(m, b):\n    mean,scale=m.statistics(b[2]);normalized=[(x.float()-mean)/scale for x in b]\n    roundtrip=max(float(((x*scale+mean)-y).abs().max()) for x,y in zip(normalized,b))\n    p=m(*b);gain=1.1;offset=0.02\n    q=m(*[x*gain+offset for x in b])\n    error=(q-(p*gain+offset)).abs()\n    return dict(roundtrip_max_abs=roundtrip,mean=mean.flatten().cpu().tolist(),scale=scale.flatten().cpu().tolist(),\n                affine_gain=gain,affine_offset=offset,affine_output_max_abs=float(error.max()),affine_output_mean_abs=float(error.mean()),\n                note=\'Affine equivariance is expected for N1 away from the std floor; quality is evaluated separately.\')\n\n\ndef rng():return dict(python=random.getstate(),numpy=np.random.get_state(),cpu=torch.get_rng_state(),cuda=torch.cuda.get_rng_state())\ndef setrng(r):random.setstate(r[\'python\']);np.random.set_state(r[\'numpy\']);torch.set_rng_state(r[\'cpu\']);torch.cuda.set_rng_state(r[\'cuda\'])\n\ndef resume_probe(m,cache,cfg,arm):\n    """Two tiny real-model AMP updates, checkpoint/reload between them, then rollback."""\n    initial=cpu(m.state_dict());initial_rng=rng()\n    folder=Path(cfg[\'out\'])/\'provenance\';path=folder/f\'resume_probe_{arm}.pt\'\n    optim=torch.optim.Adam(m.parameters(),lr=cfg[\'lr\'])\n    scaler=torch.amp.GradScaler(\'cuda\',init_scale=1024.)\n    gen=torch.Generator(device=\'cuda\').manual_seed(cfg[\'seed\']+9000)\n    order=torch.randperm(4,device=\'cuda\',generator=gen).cpu()\n    def step(position):\n        m.train();optim.zero_grad(set_to_none=True)\n        ix=order[position*2:position*2+2].cuda();batch=[cache[k].index_select(0,ix) for k in KEYS]\n        with torch.autocast(\'cuda\',dtype=torch.float16):prediction=m(*batch[:3])\n        loss=(prediction.float()-batch[3]).square().mean()\n        scaler.scale(loss).backward();scaler.step(optim);scaler.update()\n        return float(loss)\n    try:\n        step(0)\n        atomic(path,dict(model=m.state_dict(),optimizer=optim.state_dict(),scaler=scaler.state_dict(),\n                        rng=rng(),generator=gen.get_state(),order=order,next_batch=1))\n        reference_loss=step(1);reference=cpu(m.state_dict());reference_optim=cpu(optim.state_dict())\n        reference_scaler=copy.deepcopy(scaler.state_dict());reference_next=torch.randperm(4,device=\'cuda\',generator=gen).cpu()\n        ck=torch.load(path,map_location=\'cpu\',weights_only=False)\n        m.load_state_dict(ck[\'model\'],strict=True)\n        optim=torch.optim.Adam(m.parameters(),lr=cfg[\'lr\']);optim.load_state_dict(ck[\'optimizer\'])\n        for state in optim.state.values():\n            for key,value in state.items():\n                if torch.is_tensor(value) and key!=\'step\':state[key]=value.cuda()\n        scaler=torch.amp.GradScaler(\'cuda\',init_scale=1024.);scaler.load_state_dict(ck[\'scaler\'])\n        gen.set_state(ck[\'generator\']);order=ck[\'order\'];setrng(ck[\'rng\'])\n        resumed_loss=step(ck[\'next_batch\']);restored=cpu(m.state_dict())\n        max_abs=0.\n        for key,value in reference.items():\n            other=restored[key]\n            if value.is_floating_point():\n                delta=float((value-other).abs().max());max_abs=max(max_abs,delta)\n                torch.testing.assert_close(value,other,rtol=1e-5,atol=1e-6)\n            elif not torch.equal(value,other):raise AssertionError(\'Resume integer buffer differs: \'+key)\n        def assert_tree(a,b):\n            if torch.is_tensor(a):torch.testing.assert_close(a,b,rtol=1e-5,atol=1e-6)\n            elif isinstance(a,dict):\n                if a.keys()!=b.keys():raise AssertionError(\'Resume optimizer structure differs\')\n                for k in a:assert_tree(a[k],b[k])\n            elif isinstance(a,(list,tuple)):\n                if len(a)!=len(b):raise AssertionError(\'Resume optimizer length differs\')\n                for x,y in zip(a,b):assert_tree(x,y)\n            elif a!=b:raise AssertionError(\'Resume scalar differs\')\n        assert_tree(reference_optim,cpu(optim.state_dict()))\n        assert_tree(reference_scaler,scaler.state_dict())\n        if not torch.equal(reference_next,torch.randperm(4,device=\'cuda\',generator=gen).cpu()):raise AssertionError(\'Generator restore differs\')\n        if abs(reference_loss-resumed_loss)>1e-6:raise AssertionError(\'Resume loss differs\')\n        return dict(passed=True,max_model_abs=max_abs,reference_loss=reference_loss,resumed_loss=resumed_loss,\n                    scope=\'two real-model AMP updates on four train samples; optimizer/scaler/RNG/order/cursor restored\',\n                    limit=\'not a full epoch/session termination test; CUDA warn-only operations may not be bitwise deterministic\')\n    finally:\n        m.load_state_dict(initial,strict=True);setrng(initial_rng);m.zero_grad(set_to_none=True)\n        if path.exists():path.unlink()\n\n\ndef worker(cfg,arm):\n    torch.set_num_threads(1);torch.cuda.set_device(0)\n    torch.backends.cuda.matmul.allow_tf32=False;torch.backends.cudnn.allow_tf32=False;torch.backends.cudnn.benchmark=False\n    torch.use_deterministic_algorithms(True,warn_only=True)\n    seed=cfg[\'seed\'];random.seed(seed);np.random.seed(seed);torch.manual_seed(seed);torch.cuda.manual_seed(seed)\n    out=Path(cfg[\'out\'])/\'results\'/arm;out.mkdir(parents=True,exist_ok=True)\n    checkpoints=Path(cfg[\'out\'])/\'checkpoints\'/f\'{arm}_QB_s{cfg["seed"]}\';checkpoints.mkdir(parents=True,exist_ok=True)\n    lock=(out/\'run.lock\').open(\'a+b\')\n    import fcntl\n    fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)\n    def log(phase,**kw):\n        rec=dict(arm=arm,gpu=cfg[\'gpu_map\'][arm],phase=phase,time_kst=datetime.now(KST).isoformat(),allocated_gb=torch.cuda.memory_allocated()/2**30,reserved_gb=torch.cuda.memory_reserved()/2**30,peak_gb=torch.cuda.max_memory_allocated()/2**30,**kw)\n        write(out/\'status.json\',rec)\n        with (out/\'events.jsonl\').open(\'a\',encoding=\'utf8\') as stream:stream.write(json.dumps(rec,allow_nan=False)+\'\\n\')\n        print(json.dumps(rec,allow_nan=False),flush=True)\n    m=Model(arm,cfg[\'std_floor\']).cuda()\n    initial_hash=digest_state(m.state_dict())\n    write(out/\'initialization.json\',dict(state_sha256=initial_hash,parameters=sum(p.numel() for p in m.parameters()),\n          initial_outputs_equal=False,initialization=\'fresh common seed; arm introduces no extra parameters\'))\n    m.eval()\n    g=torch.Generator(device=\'cuda\').manual_seed(123)\n    test=[torch.rand(shape,device=\'cuda\',generator=g) for shape in [(1,1,64,64),(1,4,64,64),(1,4,16,16)]]\n    with torch.inference_mode():\n        actual=m(*test)\n        if arm==\'N0\':torch.testing.assert_close(actual,m.core(*test),rtol=0,atol=0)\n        if not torch.isfinite(actual).all():raise FloatingPointError(\'Preflight forward\')\n        diagnostics=normalization_diagnostics(m,test)\n        for value in (0.,0.5):\n            constant=[torch.full_like(x,value) for x in test]\n            if not torch.isfinite(m(*constant)).all():raise FloatingPointError(\'Constant-input forward\')\n    del actual,test;torch.cuda.empty_cache()\n    optimizer=torch.optim.Adam(m.parameters(),lr=cfg[\'lr\']);scaler=torch.amp.GradScaler(\'cuda\',init_scale=1024.)\n    updates=[0];optimizer.register_step_post_hook(lambda *a:updates.__setitem__(0,updates[0]+1));attempted=0\n    log(\'loading_gpu_cache\');train=gpu_cache(cfg[\'data\'][\'train\']);val=gpu_cache(cfg[\'data\'][\'val\'])\n    # A backward preflight is rolled back completely before the actual run.\n    probe_state=cpu(m.state_dict());probe_rng=rng();m.train();optimizer.zero_grad(set_to_none=True)\n    with torch.autocast(\'cuda\',dtype=torch.float16):p=m(*[train[k][:cfg[\'micro\']] for k in KEYS[:3]])\n    loss=(p.float()-train[\'gt\'][:cfg[\'micro\']]).square().mean();scaler.scale(loss).backward()\n    if not torch.isfinite(loss):raise FloatingPointError(\'Preflight loss\')\n    scaler.unscale_(optimizer)\n    if not all(p.grad is None or torch.isfinite(p.grad).all() for p in m.parameters()):raise FloatingPointError(\'Preflight gradients\')\n    m.load_state_dict(probe_state);setrng(probe_rng);optimizer=torch.optim.Adam(m.parameters(),lr=cfg[\'lr\']);scaler=torch.amp.GradScaler(\'cuda\',init_scale=1024.);updates=[0];optimizer.register_step_post_hook(lambda *a:updates.__setitem__(0,updates[0]+1));optimizer.zero_grad(set_to_none=True)\n    del probe_state,p,loss;torch.cuda.empty_cache()\n    resume_check=resume_probe(m,train,cfg,arm)\n    if digest_state(m.state_dict())!=initial_hash:raise ValueError(\'Preflight did not restore the common initial state\')\n    log(\'preflight_pass\',initial_state_sha256=initial_hash,resume_probe=resume_check)\n    write(out/\'preflight.json\',dict(forward=True,backward=True,gpu_cache=True,N0_original_equivalence=(arm==\'N0\'),normalization=diagnostics,micro=cfg[\'micro\'],effective_batch=cfg[\'batch\'],cuda_resume_equivalence=resume_check))\n    if cfg[\'mode\']==\'check\':return\n    fingerprint=cfg[\'fingerprint\'];latest=checkpoints/\'latest.pt\';history=[];epoch=0;next_batch=0;order=None;loss_sum=0.;elements=0;best_epoch=0;best_val=None;best_sd=None;durations=[];grad_diagnostics={}\n    stop=[False];signal.signal(signal.SIGTERM,lambda *a:stop.__setitem__(0,True));signal.signal(signal.SIGINT,lambda *a:stop.__setitem__(0,True))\n    generator=torch.Generator(device=\'cuda\').manual_seed(seed+100000)\n    if cfg[\'resume\']:\n        if not latest.exists():raise FileNotFoundError(f\'Missing resume state: {latest}\')\n        ck=torch.load(latest,map_location=\'cpu\',weights_only=False)\n        if ck[\'fingerprint\']!=fingerprint:raise ValueError(\'Resume source/config/data mismatch; use a new run\')\n        m.load_state_dict(ck[\'model\']);optimizer.load_state_dict(ck[\'optimizer\']);scaler.load_state_dict(ck[\'scaler\']);generator.set_state(ck[\'generator\'])\n        \n        for state in optimizer.state.values():\n            for key,value in state.items():\n                if torch.is_tensor(value) and key!=\'step\':state[key]=value.cuda()\n        epoch=ck[\'epoch\'];next_batch=ck[\'next_batch\'];order=ck[\'order\'];loss_sum=ck[\'loss_sum\'];elements=ck[\'elements\'];history=ck[\'history\'];best_epoch=ck[\'best_epoch\'];best_val=ck[\'best_val\'];best_sd=ck[\'best_model\'];attempted=ck[\'attempted\'];updates[0]=ck[\'updates\'];durations=ck[\'durations\'];setrng(ck[\'rng\'])\n        atomic(checkpoints/\'best.pt\',dict(model=best_sd,best_epoch=best_epoch,metrics=best_val,fingerprint=fingerprint,config=cfg))\n        write(out/\'history.json\',history)\n    else:\n        best_sd=cpu(m.state_dict())\n        atomic(Path(cfg[\'out\'])/\'provenance\'/f\'initial_{arm}.pt\',dict(model=best_sd,fingerprint=fingerprint,config=cfg))\n        t=time.monotonic();best_val=validation(m,val,cfg[\'micro\']);durations=[]\n        history=[dict(epoch=0,train_mse=None,**best_val)]\n        atomic(checkpoints/\'best.pt\',dict(model=best_sd,best_epoch=0,metrics=best_val,fingerprint=fingerprint,config=cfg));write(out/\'history.json\',history)\n        log(\'epoch0_validation\',**best_val)\n    def save():\n        atomic(latest,dict(model=m.state_dict(),optimizer=optimizer.state_dict(),scaler=scaler.state_dict(),rng=rng(),generator=generator.get_state(),epoch=epoch,next_batch=next_batch,order=order,loss_sum=float(loss_sum),elements=elements,history=history,best_epoch=best_epoch,best_val=best_val,best_model=best_sd,attempted=attempted,updates=updates[0],durations=durations,fingerprint=fingerprint,config=cfg))\n    save();last_save=time.monotonic();last_log=0.;n=len(train[\'pan\']);steps=math.ceil(n/cfg[\'batch\'])\n    while epoch<cfg[\'epochs\']:\n        start=time.monotonic();start_batch=next_batch;m.train()\n        if order is None:\n            order=torch.randperm(n,device=\'cuda\',generator=generator).cpu()\n        order_gpu=order.cuda();order_hash=hashlib.sha256(order.numpy().tobytes()).hexdigest()\n        acc=torch.tensor(loss_sum,device=\'cuda\',dtype=torch.float64)\n        for bi in range(next_batch,steps):\n            idx=order_gpu[bi*cfg[\'batch\']:(bi+1)*cfg[\'batch\']];denom=len(idx)*train[\'gt\'][0].numel();optimizer.zero_grad(set_to_none=True)\n            for j in range(0,len(idx),cfg[\'micro\']):\n                ix=idx[j:j+cfg[\'micro\']];b=[train[k].index_select(0,ix) for k in KEYS]\n                with torch.autocast(\'cuda\',dtype=torch.float16):p=m(*b[:3])\n                sq=(p.float()-b[3]).square().sum();scaler.scale(sq/denom).backward();acc+=sq.detach().double()\n            if bi==steps-1:\n                scaler.unscale_(optimizer)\n                grad_diagnostics={name:float(torch.sqrt(sum((p.grad.float().square().sum() for p in module.parameters() if p.grad is not None),torch.zeros((),device=\'cuda\')))) for name,module in [(\'core\',m.core)]}\n            attempted+=1;scaler.step(optimizer);scaler.update();elements+=denom;next_batch=bi+1\n            now=time.monotonic()\n            if now-last_log>=15 or bi==steps-1:\n                loss_sum=float(acc)\n                if not math.isfinite(loss_sum):raise FloatingPointError(\'Nonfinite train accumulation\')\n                eta=None\n                if durations:\n                    remaining=(cfg[\'epochs\']-epoch-1)+(steps-next_batch)/steps\n                    eta=float(np.mean(durations[-3:])*remaining)\n                log(\'train\',epoch=epoch+1,epochs=cfg[\'epochs\'],batch=next_batch,batches=steps,train_mse=loss_sum/elements,lr=cfg[\'lr\'],actual_updates=updates[0],attempted_updates=attempted,skipped_updates=attempted-updates[0],eta_seconds=eta,training_end_kst=(datetime.now(KST)+timedelta(seconds=eta)).isoformat() if eta is not None else \'측정 대기\',total_end_kst=\'평가·압축 I/O 미측정\',eta_basis=\'recent full train+validation+checkpoint epochs; current pending validation/checkpoint omitted\')\n                last_log=now\n            if now-last_save>=60 or stop[0]:\n                loss_sum=float(acc);save();last_save=time.monotonic()\n                if stop[0]:log(\'interrupted_saved\');return\n        loss_sum=float(acc);v=validation(m,val,cfg[\'micro\']);epoch+=1\n        row=dict(epoch=epoch,train_mse=loss_sum/elements,**v,order_sha256=order_hash,lr=cfg[\'lr\'],updates=updates[0],attempted=attempted,skipped=attempted-updates[0],gradient_norm_last_batch=grad_diagnostics)\n        if v[\'val_mse\']<best_val[\'val_mse\']:\n            best_val=v;best_epoch=epoch;best_sd=cpu(m.state_dict())\n        # best is always the true stored optimum, including epoch0.\n        atomic(checkpoints/\'best.pt\',dict(model=best_sd,best_epoch=best_epoch,metrics=best_val,fingerprint=fingerprint,config=cfg))\n        next_batch=0;order=None;loss_sum=0.;elements=0;history.append(row);write(out/\'history.json\',history)\n        save();torch.cuda.synchronize();duration=time.monotonic()-start\n        # Partial resumed epochs are excluded from ETA speed estimates.\n        if start_batch==0:durations.append(duration)\n        save();last_save=time.monotonic();log(\'epoch_complete\',**row,epoch_seconds=duration,best_epoch=best_epoch)\n    log(\'training_complete\',best_epoch=best_epoch)\n    if not cfg[\'evaluate_after_training\']:\n        write(out/\'training_complete.json\',dict(best_epoch=best_epoch,best_sha256=sha(checkpoints/\'best.pt\'),latest_sha256=sha(latest)))\n        return\n    evaluate(m,cfg,arm,out,log)\n    write(out/\'complete.json\',dict(state=\'training_and_evaluation_complete\',best_epoch=best_epoch,best_sha256=sha(checkpoints/\'best.pt\'),latest_sha256=sha(latest)))\n\ndef preview(arr,pred,path,label):\n    from PIL import Image,ImageDraw\n    bands=[2,1,0];ref=arr[\'gt\'][bands].transpose(1,2,0);lo,hi=np.percentile(ref,[1,99],axis=(0,1))\n    def rgb(a):return Image.fromarray((np.clip((a[bands].transpose(1,2,0)-lo)/np.maximum(hi-lo,1e-8),0,1)*255).astype(\'uint8\'))\n    pn=arr[\'pan\'][0];a,b=np.percentile(pn,[1,99]);pi=Image.fromarray((np.clip((pn-a)/max(b-a,1e-8),0,1)*255).astype(\'uint8\')).convert(\'RGB\');h,w=pn.shape\n    canvas=Image.new(\'RGB\',(4*w,h+32),\'white\');d=ImageDraw.Draw(canvas)\n    for j,(txt,im) in enumerate([(\'LR MS\',rgb(arr[\'ms\'])),(\'PAN input\',pi),(label,rgb(pred)),(\'GT\',rgb(arr[\'gt\']))]):canvas.paste(im.resize((w,h),Image.Resampling.NEAREST),(j*w,32));d.text((j*w+8,8),txt,fill=\'black\')\n    canvas.save(path)\n\n@torch.inference_mode()\ndef evaluate(m,cfg,arm,out,log):\n    checkpoints=Path(cfg[\'out\'])/\'checkpoints\'/f\'{arm}_QB_s{cfg["seed"]}\'\n    ck=torch.load(checkpoints/\'best.pt\',map_location=\'cpu\',weights_only=False);m.load_state_dict(ck[\'model\']);m.eval()\n    records={};timing={};d=out/\'results\';d.mkdir(exist_ok=True)\n    for proto in (\'RR\',\'FR\'):\n        rows=[];elapsed_scenes=[];log(\'evaluate_\'+proto)\n        with h5py.File(cfg[\'data\'][proto],\'r\') as f:\n            for i in range(len(f[\'pan\'])):\n                scene_start=time.monotonic()\n                a={k:np.asarray(f[k][i],dtype=np.float64) for k in KEYS if k in f}\n                inp=[torch.from_numpy((a[k]/2047).astype(\'float32\')).unsqueeze(0).cuda() for k in KEYS[:3]]\n                if i==0:\n                    for _ in range(3):m(*inp)\n                    times=[]\n                    for _ in range(5):\n                        torch.cuda.synchronize();start=time.perf_counter();m(*inp);torch.cuda.synchronize();times.append((time.perf_counter()-start)*1000)\n                    timing[proto]=dict(forward_median_ms=float(np.median(times)),repetitions=5,warmup=3,excludes=\'transfer and metrics\')\n                pred=m(*inp)[0].cpu().numpy().astype(\'float64\')*2047\n                if not np.isfinite(pred).all():raise FloatingPointError(\'Nonfinite test prediction\')\n                metrics=rr_metrics(a[\'gt\'],pred) if proto==\'RR\' else fr_metrics(pred,a[\'lms\'],a[\'ms\'],a[\'pan\'])\n                if not all(math.isfinite(v) for v in metrics.values()):raise FloatingPointError(\'Nonfinite test metrics\')\n                rows.append(dict(index=i,metrics=metrics))\n                if proto==\'RR\' and i in cfg[\'scenes\']:preview(a,pred,d/f\'RR_scene_{i:03}.png\',arm)\n                write(d/f\'{proto}.json\',dict(rows=rows,mean={k:float(np.mean([r[\'metrics\'][k] for r in rows])) for k in metrics}))\n                elapsed_scenes.append(time.monotonic()-scene_start)\n                remaining=float(np.mean(elapsed_scenes[-5:])*(len(f[\'pan\'])-i-1))\n                log(\'evaluate_\'+proto,scene=i+1,scenes=len(f[\'pan\']),protocol_eta_seconds=remaining,protocol_end_kst=(datetime.now(KST)+timedelta(seconds=remaining)).isoformat(),total_end_kst=\'Remaining protocol or archive I/O not yet measured\')\n        records[proto]=dict(rows=rows,mean={k:float(np.mean([r[\'metrics\'][k] for r in rows])) for k in rows[0][\'metrics\']})\n    write(d/\'metrics.json\',dict(protocols=records,best_epoch=ck[\'best_epoch\'],timing=timing,limits=[\'QNR/Q2n/SCC MATLAB parity unverified\',\'Previously inspected benchmark; no new independent holdout\',\'Single QB seed; fresh-from-scratch comparison\']))\n\nif __name__==\'__main__\':\n    cfg=json.loads(Path(sys.argv[1]).read_text());arm=sys.argv[2]\n    try:worker(cfg,arm)\n    except BaseException:\n        out=Path(cfg[\'out\'])/\'results\'/arm;out.mkdir(parents=True,exist_ok=True);write(out/\'failure.json\',dict(error=traceback.format_exc(),time=time.time()));raise\n\n', 'controller_template.py': '# 32: MS-anchored reversible brightness/contrast normalization.\n# Paste this ENTIRE file into ONE Kaggle cell. No Internet or prior weights needed.\n# Choose GPU T4 x2; attach the exact dataset named below.\n# MODE=\'train\' includes GPU preflight, 100 epochs, RR/FR scoring and ZIP creation.\n# MODE=\'check\' runs GPU preflight only; use a NEW RUN_ID when starting real training.\n# A rerun never silently overwrites an existing folder.\nMODE = \'train\'                   # \'check\' or \'train\'\nSEED = 42                       # later independent repetitions: 43, 44\nRUN_ID = \'32_ms_anchored_reversible_normalization_s42_v1\'\nRESUME_FROM = \'\'                # exact prior RUN_ID folder with config.json\nEVALUATE_AFTER_TRAINING = True   # False permits validation-only screening; resume with True to score\nDATA_ROOT = \'/kaggle/input/datasets/biyonghiyon/ctrs-pan-sharpening-dataset\'\n\nimport os,sys,json,time,hashlib,subprocess,shutil,zipfile,platform,urllib.request\nfrom pathlib import Path\n# EMBEDDED_SOURCE_BUNDLE\n\n\ndef _executed_source():\n    # Snapshot the complete pasted cell (or script), not a mutable remote URL.\n    try:\n        path=globals().get(\'__file__\')\n        if path and Path(path).is_file():\n            source=Path(path).read_text(encoding=\'utf8\')\n            if \'_BUNDLE = \' in source:return source,\'script_file\'\n    except (OSError,UnicodeError):pass\n    try:\n        shell=get_ipython()\n        for source in reversed(shell.history_manager.input_hist_raw):\n            if \'def _inspect(\' in source and \'_BUNDLE = \' in source and \'def main(\' in source:\n                return source,\'notebook_cell\'\n    except (NameError,AttributeError):pass\n    # Script exec() users may not provide source history. Reconstruct the unedited\n    # delivered controller; runtime parameters are separately preserved in config.\n    source=_BUNDLE[\'controller_template.py\'].replace(\'# EMBEDDED_SOURCE_BUNDLE\',\'_BUNDLE = \'+repr(_BUNDLE),1)\n    return source,\'reconstructed_delivered_controller\'\n\ndef _controller_fingerprint(source):\n    import ast\n    tree=ast.parse(source)\n    allowed={\'MODE\',\'RUN_ID\',\'RESUME_FROM\',\'EVALUATE_AFTER_TRAINING\',\'DATA_ROOT\'}\n    tree.body=[node for node in tree.body if not (isinstance(node,ast.Assign) and\n               any(isinstance(target,ast.Name) and target.id in allowed for target in node.targets))]\n    return hashlib.sha256(ast.dump(tree,include_attributes=False).encode()).hexdigest()\n\n\ndef _sha(p):\n    h=hashlib.sha256()\n    with open(p,\'rb\') as f:\n        for b in iter(lambda:f.read(8*1024**2),b\'\'):h.update(b)\n    return h.hexdigest()\n\ndef _write(p,obj):\n    p=Path(p);p.parent.mkdir(parents=True,exist_ok=True);t=p.with_suffix(p.suffix+\'.tmp\')\n    t.write_text(json.dumps(obj,indent=2,allow_nan=False),encoding=\'utf8\');os.replace(t,p)\n\n\ndef _inspect(data):\n    import h5py,numpy as np\n    manifests={}\n    for split,path in data.items():\n        p=Path(path)\n        if not p.is_file():raise FileNotFoundError(f\'{split}: missing exact dataset path: {p}\')\n        rows={}\n        with h5py.File(p,\'r\') as f:\n            required=(\'pan\',\'lms\',\'ms\',\'gt\') if split in (\'train\',\'val\',\'RR\') else (\'pan\',\'lms\',\'ms\')\n            if any(k not in f for k in required):raise ValueError(f\'{split} missing keys {required}\')\n            n=len(f[\'pan\']);h,w=f[\'pan\'].shape[-2:]\n            if f[\'pan\'].shape!=(n,1,h,w) or f[\'lms\'].shape!=(n,4,h,w) or f[\'ms\'].shape!=(n,4,h//4,w//4):raise ValueError(f\'{split}: unexpected NCHW or spatial ratio\')\n            if \'gt\' in required and f[\'gt\'].shape!=(n,4,h,w):raise ValueError(f\'{split}: GT shape\')\n            if min(h,w)<16 or h%4 or w%4:raise ValueError(f\'{split}: invalid spatial dimensions\')\n            for k in required:\n                ds=f[k];lo=float(\'inf\');hi=-float(\'inf\')\n                for start in range(0,n,256):\n                    a=np.asarray(ds[start:start+256]);\n                    if not np.isfinite(a).all():raise ValueError(f\'{split}/{k}: nonfinite values\')\n                    lo=min(lo,float(a.min()));hi=max(hi,float(a.max()))\n                # Cubic LMS ringing and tiny negative MS roundoff are valid. Never clip or min-max normalize.\n                if max(abs(lo),abs(hi))>32768:raise ValueError(f\'{split}/{k}: suspicious DN range {lo},{hi}\')\n                if k in (\'pan\',\'gt\') and hi<=2:raise ValueError(f\'{split}/{k}: expected raw DN values, not normalized data\')\n                rows[k]=dict(shape=list(ds.shape),dtype=str(ds.dtype),min=lo,max=hi)\n                print(f\'{split}/{k}: {lo:.8g} to {hi:.8g}; /2047 preserved\',flush=True)\n            expected={\'train\':17139,\'val\':1905,\'RR\':20,\'FR\':20}[split]\n            if n!=expected:raise ValueError(f\'{split}: expected {expected} samples, got {n}\')\n            if split in (\'RR\',\'FR\') and n!=20:raise ValueError(f\'{split}: expected 20 scenes, got {n}\')\n        manifests[split]=dict(path=str(p),sha256=_sha(p),keys=rows)\n    if len({v[\'sha256\'] for v in manifests.values()})!=4:raise ValueError(\'Duplicate split files\')\n    return manifests\n\ndef _plots(out):\n    import matplotlib;matplotlib.use(\'Agg\')\n    import matplotlib.pyplot as plt\n    hist={a:json.loads((out/\'results\'/a/\'history.json\').read_text()) for a in (\'N0\',\'N1\')}\n    fig,axs=plt.subplots(1,4,figsize=(16,4))\n    for a,rows in hist.items():\n        for ax,key in zip(axs,(\'train_mse\',\'val_mse\',\'val_psnr\',\'val_sam\')):\n            rr=[r for r in rows if r.get(key) is not None];ax.plot([r[\'epoch\'] for r in rr],[r[key] for r in rr],label=a);ax.set_title(key);ax.grid(alpha=.2)\n    axs[-1].legend();fig.tight_layout();fig.savefig(out/\'curves.png\',dpi=160);plt.close(fig)\n    metrics={a:json.loads((out/\'results\'/a/\'results/metrics.json\').read_text()) for a in (\'N0\',\'N1\')}\n    fig,axs=plt.subplots(2,4,figsize=(16,8))\n    deltas={}\n    for ax,(proto,key) in zip(axs.flat,[(\'RR\',\'PSNR\'),(\'RR\',\'SAM\'),(\'RR\',\'ERGAS\'),(\'RR\',\'SCC\'),(\'RR\',\'Q2n\'),(\'FR\',\'QNR\'),(\'FR\',\'D_lambda\'),(\'FR\',\'D_s\')]):\n        v=[metrics[a][\'protocols\'][proto][\'mean\'][key] for a in (\'N0\',\'N1\')];ax.bar([\'N0\',\'N1\'],v);ax.set_title(proto+\' \'+key+(\' (provisional)\' if proto==\'FR\' else \'\'));deltas[proto+\'_\'+key]=v[1]-v[0]\n    fig.tight_layout();fig.savefig(out/\'comparison.png\',dpi=160);plt.close(fig)\n    paired={}\n    for proto in (\'RR\',\'FR\'):\n        r0=metrics[\'N0\'][\'protocols\'][proto][\'rows\'];r1=metrics[\'N1\'][\'protocols\'][proto][\'rows\']\n        if len(r0)!=20 or len(r1)!=20:raise ValueError(\'Incomplete test\')\n        paired[proto]=[dict(index=x[\'index\'],delta={k:y[\'metrics\'][k]-x[\'metrics\'][k] for k in x[\'metrics\']}) for x,y in zip(r0,r1) if x[\'index\']==y[\'index\']]\n        if len(paired[proto])!=20:raise ValueError(\'Scene alignment mismatch\')\n    _write(out/\'paired_scene_deltas.json\',paired)\n    # Thresholds are preregistered screening targets, not statistical significance.\n    v0=min(r[\'val_mse\'] for r in hist[\'N0\']);v1=min(r[\'val_mse\'] for r in hist[\'N1\'])\n    d0=metrics[\'N0\'][\'protocols\'][\'FR\'][\'mean\'];d1=metrics[\'N1\'][\'protocols\'][\'FR\'][\'mean\']\n    _write(out/\'summary.json\',dict(deltas=deltas,validation_screen_pass=v1<=v0*1.005,rr_screen_pass=deltas[\'RR_PSNR\']>=-.03 and deltas[\'RR_SAM\']<=.02,fr_screen_pass=deltas[\'FR_QNR\']>=.003 and d1[\'D_lambda\']<=d0[\'D_lambda\'] and d1[\'D_s\']<=d0[\'D_s\'],status=\'single-seed exploratory comparison; no automatic baseline promotion\',metrics=metrics))\n\ndef _verify_pair(out,cfg):\n    arms=(\'N0\',\'N1\')\n    initial=[json.loads((out/\'results\'/arm/\'initialization.json\').read_text()) for arm in arms]\n    if initial[0][\'state_sha256\']!=initial[1][\'state_sha256\']:raise ValueError(\'Common initialization differs\')\n    histories=[json.loads((out/\'results\'/arm/\'history.json\').read_text()) for arm in arms]\n    for history in histories:\n        if [r[\'epoch\'] for r in history]!=list(range(cfg[\'epochs\']+1)):raise ValueError(\'Missing epoch records\')\n    orders=[[r[\'order_sha256\'] for r in history[1:]] for history in histories]\n    if orders[0]!=orders[1]:raise ValueError(\'Actual batch orders differ\')\n    skipped=[history[-1][\'skipped\'] for history in histories]\n    if any(skipped):raise ValueError(\'AMP skipped updates found. Results preserved, comparison requires review: \'+str(skipped))\n    _write(out/\'pair_verification.json\',dict(initial_parameters_equal=True,actual_epoch_orders_equal=True,\n            completed_epochs=cfg[\'epochs\'],skipped_updates=skipped,bitwise_cuda_reproducibility_guaranteed=False))\n\ndef _training_plots(out):\n    import matplotlib;matplotlib.use(\'Agg\')\n    import matplotlib.pyplot as plt\n    fig,axs=plt.subplots(1,4,figsize=(16,4))\n    for arm in (\'N0\',\'N1\'):\n        rows=json.loads((out/\'results\'/arm/\'history.json\').read_text())\n        for ax,key in zip(axs,(\'train_mse\',\'val_mse\',\'val_psnr\',\'val_sam\')):\n            rr=[r for r in rows if r.get(key) is not None]\n            ax.plot([r[\'epoch\'] for r in rr],[r[key] for r in rr],label=arm)\n            ax.set_title(key);ax.grid(alpha=.2)\n    axs[-1].legend();fig.tight_layout();fig.savefig(out/\'curves.png\',dpi=160);plt.close(fig)\n\ndef _verify_artifacts(out,cfg):\n    needed=[\'curves.png\',\'comparison.png\',\'pair_verification.json\',\'paired_scene_deltas.json\',\'summary.json\',\'selection.json\',\'data_manifest.json\',\'config.json\']\n    for arm in (\'N0\',\'N1\'):\n        needed += [f\'checkpoints/{arm}_QB_s{cfg["seed"]}/{name}.pt\' for name in (\'best\',\'latest\')]\n        needed += [f\'results/{arm}/{name}\' for name in (\'preflight.json\',\'initialization.json\',\'history.json\',\'complete.json\',\'results/metrics.json\')]\n        needed += [f\'results/{arm}/results/RR_scene_{i:03}.png\' for i in cfg[\'scenes\']]\n    for path in needed:\n        if not (out/path).is_file() or (out/path).stat().st_size==0:raise ValueError(\'Missing artifact: \'+path)\n    for arm in (\'N0\',\'N1\'):\n        rec=json.loads((out/\'results\'/arm/\'complete.json\').read_text())\n        ck=out/\'checkpoints\'/f\'{arm}_QB_s{cfg["seed"]}\'\n        for name in (\'best\',\'latest\'):\n            if rec[name+\'_sha256\']!=_sha(ck/(name+\'.pt\')):raise ValueError(\'Checkpoint hash mismatch\')\n    _write(out/\'artifact_verification.json\',dict(required_files=needed,all_exist_nonempty=True,checkpoint_hashes_match=True,\n           training_complete=True,evaluation_complete=True,remote_retention_verified=False))\n\n\ndef _archive(out,complete):\n    items={}\n    for p in sorted(out.rglob(\'*\')):\n        if p.is_file() and \'__pycache__\' not in p.parts and p.suffix!=\'.pyc\' and p.name not in (\'manifest.json\',\'controller.lock\') and p.suffix not in (\'.tmp\',\'.download\') and p.name!=\'run.lock\':items[str(p.relative_to(out))]=dict(bytes=p.stat().st_size,sha256=_sha(p))\n    _write(out/\'manifest.json\',dict(files=items,state=\'complete\' if complete else (\'training_complete_evaluation_pending\' if (out/\'training_only.json\').exists() else \'partial\'),remote_retention_verified=False,checkpoint_resume_requires=\'both latest.pt and matching config/source/data\'))\n    zip_path=out.parent/(out.name+(\'_results.zip\' if complete else (\'_training.zip\' if (out/\'training_only.json\').exists() else \'_recovery.zip\')))\n    with zipfile.ZipFile(zip_path.with_suffix(\'.tmp\'), \'w\',compression=zipfile.ZIP_DEFLATED,compresslevel=1) as z:\n        for rel in [*items,\'manifest.json\']:z.write(out/rel,arcname=out.name+\'/\'+rel)\n    os.replace(zip_path.with_suffix(\'.tmp\'),zip_path)\n    with zipfile.ZipFile(zip_path) as z:\n        bad=z.testzip()\n        if bad:raise ValueError(\'ZIP CRC failed: \'+bad)\n        for rel,info in items.items():\n            if hashlib.sha256(z.read(out.name+\'/\'+rel)).hexdigest()!=info[\'sha256\']:raise ValueError(\'ZIP SHA256 mismatch: \'+rel)\n    zip_path.with_suffix(\'.zip.sha256\').write_text(_sha(zip_path)+\'  \'+zip_path.name+\'\\n\')\n    print((\'COMPLETE LOCAL OUTPUT: \' if complete else \'PARTIAL RECOVERY OUTPUT: \')+str(zip_path),flush=True)\n    print(\'This confirms local output only. Verify Saved Version Output and download its ZIP before ending storage.\',flush=True)\n    try:\n        from IPython.display import display,FileLink\n        display(FileLink(str(zip_path)));display(FileLink(str(zip_path.with_suffix(\'.zip.sha256\'))))\n    except ImportError:pass\n\ndef main():\n    import importlib.util\n    missing=[name for name in (\'torch\',\'h5py\',\'numpy\',\'scipy\',\'skimage\',\'PIL\',\'matplotlib\') if importlib.util.find_spec(name) is None]\n    if missing:raise RuntimeError(\'Missing dependencies: \'+str(missing)+\'; use a Kaggle GPU notebook image with these packages.\')\n    import torch\n    if not RUN_ID.replace(\'_\',\'\').replace(\'-\',\'\').isalnum():raise ValueError(\'RUN_ID must be a plain folder name\')\n    if (\'_s\'+str(SEED)+\'_\') not in RUN_ID:raise ValueError(\'Update RUN_ID to match SEED\')\n    if MODE not in (\'check\',\'train\'):raise ValueError(\'MODE must be check or train\')\n    if torch.cuda.device_count()!=2:raise RuntimeError(\'Select GPU T4 x2 before running; no CPU/single-GPU fallback.\')\n    if any(\'T4\' not in torch.cuda.get_device_name(i) for i in range(2)):raise RuntimeError(\'This fixed run targets two T4 GPUs.\')\n    print(\'GPUs:\',[torch.cuda.get_device_name(i) for i in range(2)],flush=True)\n    out=Path(\'/kaggle/working\')/RUN_ID\n    import fcntl\n    control_lock=Path(\'/kaggle/working\')/(RUN_ID+\'.controller.lock\');lock=control_lock.open(\'a+b\');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)\n    resume=bool(RESUME_FROM)\n    if resume:\n        old=Path(RESUME_FROM)\n        if (old/\'manifest.json\').is_file():\n            previous=json.loads((old/\'manifest.json\').read_text())\n            for rel,info in previous[\'files\'].items():\n                path=old/rel\n                if not path.is_file() or path.stat().st_size!=info[\'bytes\'] or _sha(path)!=info[\'sha256\']:raise ValueError(\'Saved Output integrity check failed: \'+rel)\n        if not (old/\'config.json\').exists():raise FileNotFoundError(\'RESUME_FROM must be the exact prior run folder containing config.json\')\n        if old.resolve()!=out.resolve():\n            if out.exists():raise FileExistsError(\'Destination exists; choose exact same-session resume or a fresh RUN_ID\')\n            shutil.copytree(old,out)\n    elif out.exists():raise FileExistsError(f\'Existing run is protected: {out}. Set RESUME_FROM to resume or change RUN_ID for new work.\')\n    out.mkdir(parents=True,exist_ok=True)\n    _write(out/\'environment.json\',dict(python=sys.version,torch=torch.__version__,cuda=torch.version.cuda,cudnn=torch.backends.cudnn.version(),platform=platform.platform(),gpus=[torch.cuda.get_device_name(i) for i in range(2)]))\n    src=out/\'provenance/source\'\n    for name,content in _BUNDLE.items():\n        p=src/name;p.parent.mkdir(parents=True,exist_ok=True)\n        if p.exists() and p.read_bytes()!=content.encode(\'utf8\'):raise ValueError(\'Saved source differs; start a new run\')\n        p.write_bytes(content.encode(\'utf8\'))\n    data={k:str(Path(DATA_ROOT)/v) for k,v in dict(train=\'QuickBird__Training_Dataset__train_qb.h5\',val=\'QuickBird__Training_Dataset__valid_qb.h5\',RR=\'QuickBird__Testing_Dataset_ReducedData_H5_Format__test_qb_multiExm1.h5\',FR=\'QuickBird__Testing_Dataset_FullData_H5_Format__test_qb_OrigScale_multiExm1.h5\').items()}\n    manifests=_inspect(data);_write(out/\'data_manifest.json\',manifests)\n    executed,source_capture=_executed_source()\n    controller_hash=_controller_fingerprint(executed)\n    cfg=dict(controller_sha256=controller_hash,out=str(out),data=data,seed=SEED,epochs=100,batch=64,micro=32,lr=1e-4,std_floor=0.01,\n             mode=MODE,resume=resume,gpu_map={\'N0\':0,\'N1\':1},scenes=[1,8,11,13,19],\n             evaluate_after_training=EVALUATE_AFTER_TRAINING,\n             source_commit=\'2878e9bbf273edaeafd2b1251a8aed0227f06a19\',\n             source_hashes={k:hashlib.sha256(v.encode()).hexdigest() for k,v in _BUNDLE.items()},\n             precision=\'AMP FP16 train; FP32 stats/inverse/loss/validation/test; TF32 off\',\n             selection=\'minimum validation MSE including epoch0; earliest exact tie\',\n             experiment=32,research_track=\'performance\',experimenter=\'김경찬\',\n             model=\'fresh original RestoredPansharpeningNet K4; N1 shared per-sample MS affine wrapper\',\n             data_normalization=\'DN/2047; no clipping; GT excluded from input statistics\')\n    stable={k:v for k,v in cfg.items() if k not in (\'out\',\'resume\',\'data\',\'mode\',\'evaluate_after_training\')};stable[\'data_hashes\']={k:v[\'sha256\'] for k,v in manifests.items()}\n    cfg[\'fingerprint\']=hashlib.sha256(json.dumps(stable,sort_keys=True).encode()).hexdigest()\n    cp=out/\'config.json\'\n    if resume and json.loads(cp.read_text())[\'fingerprint\']!=cfg[\'fingerprint\']:raise ValueError(\'Resume incompatible with source/config/data\')\n    for arm in (\'N0\',\'N1\'):\n        folder=out/\'results\'/arm\n        for name in (\'failure.json\',\'complete.json\',\'training_complete.json\'):\n            marker=folder/name\n            if marker.exists():marker.unlink()\n    if (out/\'training_only.json\').exists():(out/\'training_only.json\').unlink()\n    (out/\'provenance\'/\'run_cell.py\').write_text(executed,encoding=\'utf8\')\n    _write(out/\'provenance\'/\'controller_capture.json\',dict(method=source_capture,canonical_sha256=controller_hash,raw_sha256=hashlib.sha256(executed.encode()).hexdigest()))\n    _write(cp,cfg);_write(out/\'selection.json\',dict(seed=SEED,indices=cfg[\'scenes\'],index_base=0,unit=\'full RR scene\',rule=\'fixed before training/test scoring\',display_order=cfg[\'scenes\'],panels=[\'LR MS nearest\',\'PAN\',\'prediction\',\'GT\'],rgb_bands=[2,1,0],contrast=\'per-scene GT 1st/99th percentile shared across MS panels\',FR_has_GT=False))\n    _write(out/\'protocol.json\',dict(experiment=32,RR=\'20 full scenes, peak2047 per-band PSNR averaged per scene\',FR=\'20 full scenes; QNR/D_lambda/D_s provisional\',std=\'population variance over C,H,W of LR MS per sample, floor=0.01\',loss=\'MSE after inverse in DN/2047 units\',predefined_targets=dict(RR_PSNR_min_delta=-.03,RR_SAM_max_delta=.02,FR_QNR_min_delta=.003),test_tuning=False))\n    handles=[];complete=False\n    try:\n        for arm,gpu in cfg[\'gpu_map\'].items():\n            env=dict(os.environ,CUDA_VISIBLE_DEVICES=str(gpu),CUBLAS_WORKSPACE_CONFIG=\':4096:8\',PYTHONUNBUFFERED=\'1\')\n            f=(out/\'results\'/arm/\'worker.log\');f.parent.mkdir(parents=True,exist_ok=True);stream=f.open(\'a\',encoding=\'utf8\')\n            proc=subprocess.Popen([sys.executable,\'-u\',str(src/\'worker.py\'),str(cp),arm],env=env,stdout=stream,stderr=subprocess.STDOUT);handles.append((arm,proc,stream))\n        last={};initial_pair_checked=False\n        while any(p.poll() is None for _,p,_ in handles):\n            for arm,p,f in handles:\n                status=out/\'results\'/arm/\'status.json\'\n                if status.exists():\n                    s=status.read_text()\n                    if s!=last.get(arm):print(s,flush=True);last[arm]=s\n            initial_files=[out/\'results\'/a/\'initialization.json\' for a in (\'N0\',\'N1\')]\n            if not initial_pair_checked and all(p.exists() for p in initial_files):\n                initial_pair_checked=True\n                if len({json.loads(p.read_text())[\'state_sha256\'] for p in initial_files})!=1:raise ValueError(\'Common initialization differs; stopping both workers\')\n            # Fail promptly and request a safe checkpoint from a surviving peer.\n            if any(p.poll() is not None and p.returncode!=0 for _,p,_ in handles):\n                for _,p,_ in handles:\n                    if p.poll() is None:p.terminate()\n                break\n            time.sleep(5)\n        for arm,p,f in handles:\n            rc=p.wait();f.close()\n            if rc:\n                print((out/\'results\'/arm/\'worker.log\').read_text()[-12000:],flush=True)\n                raise RuntimeError(f\'{arm} failed, exit {rc}; see results/{arm}/worker.log\')\n        if MODE==\'check\':\n            print(\'CHECK PASS: two GPU-resident caches, common fresh initialization, finite forward/backward; training not started.\',flush=True);return\n        if not EVALUATE_AFTER_TRAINING:\n            for arm in (\'N0\',\'N1\'):\n                if not (out/\'results\'/arm/\'training_complete.json\').is_file():raise RuntimeError(\'Training interrupted; resume required\')\n            _verify_pair(out,cfg)\n            _training_plots(out)\n            _write(out/\'training_only.json\',dict(state=\'training_complete_evaluation_pending\',test_scored=False))\n            print(\'TRAINING COMPLETE; RR/FR intentionally not scored. Inspect validation before further experiments.\',flush=True)\n            return\n        for arm in (\'N0\',\'N1\'):\n            if not (out/\'results\'/arm/\'complete.json\').exists():raise RuntimeError(f\'{arm} stopped safely before completion; resume required\')\n        init=[json.loads((out/\'results\'/a/\'initialization.json\').read_text()) for a in (\'N0\',\'N1\')]\n        if init[0][\'state_sha256\']!=init[1][\'state_sha256\']:raise ValueError(\'Initial states differ\')\n        hs=[json.loads((out/\'results\'/a/\'history.json\').read_text())[1:] for a in (\'N0\',\'N1\')]\n        if [r[\'order_sha256\'] for r in hs[0]]!=[r[\'order_sha256\'] for r in hs[1]]:raise ValueError(\'Actual epoch orders differ\')\n        for a in (\'N0\',\'N1\'):\n            for i in cfg[\'scenes\']:\n                if not (out/\'results\'/a/\'results\'/f\'RR_scene_{i:03}.png\').is_file():raise ValueError(\'Missing selected preview\')\n        _verify_pair(out,cfg);_plots(out);_verify_artifacts(out,cfg);complete=True\n    finally:\n        for _,p,f in handles:\n            if p.poll() is None:p.terminate()\n        for _,p,f in handles:\n            try:p.wait(timeout=60)\n            except subprocess.TimeoutExpired:p.kill();p.wait()\n            if not f.closed:f.close()\n        _archive(out,complete)\n\nif __name__ == \'__main__\':\n    main()\n\n', 'experiment_plan.md': '# MS 기준 가역 밝기·대비 정규화\n\n**연구 분야:** 기존 성능 개선\n\n**실험자:** 김경찬(계획 기준이며 실제 학습은 아직 실행하지 않았습니다.)\n\n**변경 내용:** 원본 SSA-MRN K4의 앞뒤에 LR MS 통계로 정규화·역변환을 추가합니다. PAN·LMS·MS와 모든 밴드에 동일한 샘플별 스칼라 변환을 적용합니다.\n\n| 확인된 결과 | 상태 | 개선 여부 |\n|---|:---:|:---:|\n| CPU 합성 데이터에서 원본 동등성, 유한 forward/backward, 정규화 복원과 체크포인트 재개를 확인했습니다. 실제 학습·RR·FR은 미실행입니다. | 계획 | 판단 보류 |\n\n## 1. 목적과 상태\n\nRR 개선과 FR 악화가 반복된 선행 결과를 바탕으로 입력의 밝기·대비 변화에 대한 민감도를 줄이는 가설을 검증합니다. 분포 차이가 기존 FR 악화의 원인이라고 확정하지 않습니다. CPU 검사는 성능 평가가 아닙니다. CUDA·실제 H5는 Kaggle에서 자동 사전 검사합니다.\n\n## 2. 변경한 구조와 비교 조건\n\nN0는 원본 RestoredPansharpeningNet의 forward(pan,lms,ms)입니다. N1은 LR MS의 C,H,W 전체에서 샘플별 평균 μ와 모집단 표준편차 s를 구합니다. s의 하한은 DN/2047 공간에서 0.01입니다. PAN·LMS·MS 모두 (x-μ)/s로 변환하고 원본 네트워크를 호출한 뒤 출력에 s를 곱하고 μ를 더합니다. 통계 계산과 입력 변환·역변환은 FP32입니다. 손실은 원래 DN/2047 단위로 복원한 최종 출력의 MSE입니다. GT는 입력 통계에 사용하지 않습니다.\n\n원본 LRPAN 경로, 네 차례 잔차 블록의 BatchNorm, SSAI와 보간을 유지합니다. 두 모델의 파라미터 수는 각각 426,654개입니다. 유효 배치만 같더라도 BatchNorm은 micro batch에 영향을 받으므로 두 군 모두 micro32로 고정합니다. 같은 초기 파라미터가 같은 초기 출력을 의미하지는 않습니다.\n\n| 항목 | 사전 고정 조건 |\n|---|---|\n| 데이터 | QB train17,139·validation1,905·RR20·FR20, 기존 분할 |\n| K·공간비 | K4·4배 |\n| 초기화 | seed42, 두 군 같은 초기 모델, 과거 가중치 사용 안 함 |\n| 학습 | 100에포크, Adam lr1e-4 고정, effective64·micro32 |\n| 정밀도 | 학습 FP16 AMP, 통계·역변환·손실 FP32, validation/test FP32, TF32 비활성 |\n| 선택 | epoch0 포함 validation MSE 최소, 정확한 동률은 최초 시점 |\n| 장치 | GPU0 N0·GPU1 N1, 독립 process, worker별 train/val GPU상주 |\n| 평가 | 전체 장면 추론, 원래 DN 단위, 입력·예측 clipping 없이 기존 지표 |\n| 예시 | RR 인덱스1·8·11·13·19, 전체 장면, LR MS·PAN·예측·GT |\n\n에포크별 실제 순서 해시와 초기 상태 해시를 비교합니다. AMP 업데이트 누락은 기록하고 비교 완료 판정을 보류합니다. micro batch를 임의로 줄이거나 CPU fallback을 적용하지 않습니다.\n\n## 3. 정량 결과\n\n실제 validation 및 RR·FR 지표는 없습니다. 실행 후 각 군의 results/<군>/history.json과 results/<군>/results/metrics.json에 기록합니다. CPU 합성 손실은 디버그 값이며 연구 성능 표에 넣지 않습니다. RR PSNR·SAM·ERGAS·SCC·Q2n, FR QNR·Dλ·Ds를 전체20장 평균과 장면별로 보존합니다. Dλ·Ds는 낮을수록 좋습니다. QNR·Q2n·SCC의 공식 MATLAB 정합은 미검증입니다.\n\n## 4. 기준선 대비 차이와 해석\n\n28번·31번 G5 미세조정 결과와 직접 비교하지 않습니다. 같은 실행에서 새로 학습한 N0만 직접 대조군입니다. 저주파를 지우거나 보정기를 추가하지 않습니다. UniPAN은 비선형 분포 변환을 연구했으며 이번 공유 affine 가역 변환은 논문의 완전한 재현이 아닙니다. RevIN은 시계열 논문이며 팬샤프닝 개선을 보장하지 않습니다. 세계 최초라고 주장하지 않습니다.\n\n주요 한계는 학습 패치와 전체 추론 장면의 통계 범위 차이입니다. 공유 affine 변환은 모든 센서·밴드별 응답 차이와 정합·공간 열화 차이를 해결하지 않습니다. 표준편차 하한이 활성화되면 엄밀한 affine equivariance는 깨집니다. CUDA 결정성 미지원 연산은 경고를 허용하므로 비트 재현성을 보장하지 않습니다.\n\n## 5. 학습·평가 그래프\n\n현재 실제 곡선은 없습니다. 실행 후 train MSE·validation MSE·PSNR·SAM 및 RR·FR 8지표 비교 그래프를 생성합니다. 없는 곡선을 추정해 만들지 않습니다.\n\n## 6. 결과 이미지\n\n현재 예측 이미지는 없습니다. 사전 고정한 RR 다섯 장면을 각각 LR MS·PAN·예측·GT로 저장합니다. RGB 밴드[2,1,0]이며 GT의1·99백분위 대비를 모든 MS 패널에 공통 적용합니다. LR MS만 최근접 확대로 표시합니다. FR에는 GT를 만들지 않습니다.\n\n## 7. 재현 자료\n\n단일 셀 run.py에는 원본 모델·기존 지표·정규화 모델·worker·controller 소스가 포함됩니다. 외부 다운로드와 부모 체크포인트가 필요하지 않습니다. 실행하면 provenance/source에 실제 사용 소스, config.json에 설정, data_manifest.json에 원본 H5의 해시·shape·범위를 남깁니다. 초기 모델과 best/latest 원본, optimizer·scaler·RNG·GPU배치 생성기·순서·다음 배치 위치·실제 이력을 보존합니다.\n\nlocal_checks.py와 local_verification.json은 CPU 합성 데이터 검사 자료입니다. Kaggle 사전 검사는 실제 GPU 캐시·AMP backward·두 업데이트 중단재개를 추가 확인하며 모델 상태·optimizer·scaler·RNG를 원복한 뒤 본 학습을 시작합니다. 이 짧은 검사와 장시간 전체 세션 중단재개 검증은 구분합니다.\n\n관련 문헌:\n- UniPAN: https://arxiv.org/abs/2510.22217\n- RevIN 공식 구현: https://github.com/ts-kim/RevIN\n- PAN-Crafter: https://kaist-viclab.github.io/PAN-Crafter_site/\n- 기준 저장소: https://github.com/BIYONGHIYON/CtrS\n\n## 8. 개선 여부와 다음 단계\n\n현재 판단 보류입니다. RR 유지 목표는 ΔPSNR≥−0.03dB·ΔSAM≤+0.02°이며 FR 목표는 잠정 ΔQNR≥+0.003·Dλ와Ds 비악화입니다. 이 임계값은 실용적인 screening 목표이며 통계적 유의성을 의미하지 않습니다. 전체 개선은 반복seed의 주요 RR·FR 동시 개선을 확인해야 합니다.\n\nseed42 이후 추가 실험 여부를 validation으로 결정하려면 EVALUATE_AFTER_TRAINING=False로 시작합니다. 학습이 끝난 동일 실행을 RESUME_FROM으로 연결하고 이 값만 True로 바꾸면 추가 학습 없이 best 평가를 수행합니다. test를 본 뒤 설정·학습량·best를 변경하지 않습니다. 다음 seed는 새 RUN_ID로 시작합니다. 기존 benchmark는 이미 반복 관찰했으므로 새 독립 holdout이라고 주장하지 않습니다. 코드·결과의 커밋·푸시는 별도 요청 시 진행합니다.\n', 'KAGGLE_GUIDE.md': "# 32번 실행·재개·결과 보관\n\n## 처음 실행\n\n1. 새 Kaggle Notebook을 만들고 GPU T4×2를 선택합니다.\n2. CtrS PAN Sharpening Dataset을 Input에 연결합니다. 파일 경로 기본값은 코드에 포함되어 있습니다.\n3. run.py 전체를 하나의 코드 셀에 붙여 넣습니다. 외부 다운로드와 이전 가중치가 필요 없어 Internet OFF로 실행할 수 있습니다.\n4. 기본값 MODE='train', SEED=42를 유지합니다. 전체 GPU 사전 검사 후 N0·N1 각각100에포크를 학습하고 RR·FR 평가·ZIP 생성을 이어서 수행합니다.\n5. Save Version → Save & Run All로 실행합니다. 이 동작은 편집 세션과 별도의 세션에서 실행됩니다. 편집 창의 세모 실행과 별도 버전 실행을 동시에 시작하지 않습니다.\n6. 두 군의 preflight_pass를 확인합니다. train 로그의 첫 완전한 에포크 이후 실제 속도 기반 ETA가 나옵니다. 학습 ETA에는 현재 대기 중 validation/checkpoint 일부가 누락될 수 있으며 평가·압축 미측정 구간은 전체 종료 예상에 포함되지 않습니다.\n\n학습 전 검사만 원하면 MODE='check'와 별도 RUN_ID를 사용합니다. 체크 실행 폴더에는 본 학습용 latest가 없으므로 체크 폴더를 학습 재개로 사용하지 않습니다. 정상 학습도 같은 검사를 자동 수행하므로 바로 train으로 시작해도 됩니다.\n\n## 로그 의미\n\n- N0: 원본 SSA-MRN입니다.\n- N1: MS 기준 가역 밝기·대비 정규화입니다.\n- loading_gpu_cache: 각 worker가 train·validation을 자신의 GPU에 적재합니다.\n- preflight_pass: 해당 Kaggle 실행에서 유한 forward/backward, N0 원본 대응, 짧은 AMP 중단재개 검사 등을 통과했습니다.\n- epoch0_validation: 무작위 초기 모델을 평가합니다. 두 군 초기 출력은 다를 수 있습니다.\n- train / epoch_complete: 실제 손실, 업데이트 수, 메모리, 시간과 검증 결과입니다.\n- COMPLETE LOCAL OUTPUT: 로컬 산출물·전체 평가·해시·ZIP 확인을 완료했습니다. 원격 보관 완료를 뜻하지 않습니다.\n\n## Validation만 먼저 확인하기\n\n추가seed 여부를 test 전에 결정하려면 시작 전 EVALUATE_AFTER_TRAINING=False로 설정합니다. training.zip을 보존하고 validation 이력을 확인합니다. 같은 설정의 동일 학습을 RESUME_FROM으로 재개하면서 이 값만 True로 바꾸면100에포크를 다시 학습하지 않고 기존best의 평가를 수행합니다. 나머지 학습 설정과 코드 변경은 fingerprint 불일치로 거부합니다.\n\n## 중단·재개\n\nlatest.pt는 약60초마다 유효 배치 경계에서 원자적으로 저장하며 매 에포크 검증 후에도 저장합니다. best.pt는 epoch0 포함 validation MSE 최솟값의 모델입니다. latest 안에 best_model도 포함되어 best 파일이 유실되어도 복원할 수 있습니다. 다만 정상 manifest가 있는데 파일이 유실된 경우에는 먼저 무결성 검사에서 중단합니다. 별도 복구가 필요하다는 신호이며 검사를 임의로 제거하지 않습니다.\n\n같은 세션에서 중단했다면:\n\n    RESUME_FROM = '/kaggle/working/32_ms_anchored_reversible_normalization_s42_v1'\n\nRUN_ID와 다른 설정은 그대로 유지합니다. 저장한 에포크 순서와 다음 배치부터 이어갑니다. 마지막 저장 이후 실행한 배치는 다시 실행될 수 있습니다.\n\n새 세션에서는 이전 Saved Output을 Notebook Input으로 연결합니다. ZIP만 연결했다면 파일을 먼저 별도 위치에 풀어야 합니다. 이전 실행 폴더의 config.json·provenance/source·두latest가 모두 있어야 합니다. RESUME_FROM은 Input 아래의 실제 실행 폴더로 지정합니다. 새 /kaggle/working 목적지와 이름이 같아도 해당 목적지가 아직 없어야 복사가 가능합니다. 자동 경로 추측이나 무관한 가중치 선택은 하지 않습니다.\n\n코드·설정·데이터가 달라졌다면 동일 실험으로 재개하지 말고 새RUN_ID에서 처음부터 시작합니다. Saved Output 폴더를 다른 새 코드로 덮어쓰지 않습니다. seed43·44는 SEED와 RUN_ID를 함께 바꾸고 RESUME_FROM=''로 새 학습합니다.\n\n## 저장과 안전한 종료\n\n- 설정에 Session Persistence가 제공되면 Files only 또는 해당 파일 보존 옵션을 선택할 수 있습니다. 이 기능은 best effort이며 별도 보관을 대체하지 않습니다. 계정·UI에 따른 현재 옵션을 확인해야 합니다.\n- Draft 코드 저장과 checkpoint 보관은 다릅니다. Save & Run All이 새 세션에서 시작되므로 이전 학습 재개에는 Saved Output의 Input 연결과 RESUME_FROM 지정이 필요합니다.\n- 버전이 끝나면 Notebook Viewer의 Output에서 결과ZIP과 .zip.sha256, 실행 폴더의 checkpoints/N0_QB_s42 및 N1_QB_s42/best.pt·latest.pt, manifest.json이 실제로 보이는지 확인합니다.\n- ZIP과 해시를 다운로드해 별도 위치에 보관합니다. ZIP CRC와 manifest의 SHA256을 확인하고 실제 best/latest를 열어 복구 가능 여부를 확인한 뒤 보관 완료로 봅니다.\n- 본 코드의 ZIP 해시 검사는 Kaggle 로컬 생성물만 확인합니다. 원격Saved Output이나 다운로드 파일은 자동으로 확인하지 않습니다.\n- 단일 배치·validation·저장 시간이 길면 체크포인트 간격이60초를 넘을 수 있습니다. SIGTERM/SIGINT는 안전한 배치 경계 저장을 시도하지만 강제 종료·런타임 삭제·SIGKILL에는 저장이 보장되지 않습니다. controller는 종료 요청 후 최대60초 기다린 뒤 종료할 수 있습니다.\n- 원격Saved Output·Dataset·다운로드 복사본 어디에도 없는 삭제된 결과는 코드로 복구할 수 없습니다.\n\n공식 안내 확인: https://www.kaggle.com/docs/notebooks\nPersistence 안내: https://www.kaggle.com/product-feedback/355440\n현재 로그인 계정의 실제 설정 화면은 이번 작업에서 확인하지 않았습니다.\n\n## 검증 범위\n\n전달 파일은 CPU 합성 데이터의 실제 모델 forward/backward, N0 동등성, 가역 변환, 상수/낮은 대비 입력, 샘플 통계 독립성, Adam/BatchNorm/배치 순서 체크포인트 복구를 통과했습니다. 이는 실제 데이터 성능 결과가 아닙니다. 실제H5·T4 AMP·GPU상주·장시간 중단재개·RR/FR 수치는 아직 미검증입니다. Kaggle에서 사전 검사 실패 시 임의로 fallback하거나 에러를 무시하지 않습니다.\n"}


def _executed_source():
    # Snapshot the complete pasted cell (or script), not a mutable remote URL.
    try:
        path=globals().get('__file__')
        if path and Path(path).is_file():
            source=Path(path).read_text(encoding='utf8')
            if '_BUNDLE = ' in source:return source,'script_file'
    except (OSError,UnicodeError):pass
    try:
        shell=get_ipython()
        for source in reversed(shell.history_manager.input_hist_raw):
            if 'def _inspect(' in source and '_BUNDLE = ' in source and 'def main(' in source:
                return source,'notebook_cell'
    except (NameError,AttributeError):pass
    # Script exec() users may not provide source history. Reconstruct the unedited
    # delivered controller; runtime parameters are separately preserved in config.
    source=_BUNDLE['controller_template.py'].replace('# EMBEDDED_SOURCE_BUNDLE','_BUNDLE = '+repr(_BUNDLE),1)
    return source,'reconstructed_delivered_controller'

def _controller_fingerprint(source):
    import ast
    tree=ast.parse(source)
    allowed={'MODE','RUN_ID','RESUME_FROM','EVALUATE_AFTER_TRAINING','DATA_ROOT'}
    tree.body=[node for node in tree.body if not (isinstance(node,ast.Assign) and
               any(isinstance(target,ast.Name) and target.id in allowed for target in node.targets))]
    return hashlib.sha256(ast.dump(tree,include_attributes=False).encode()).hexdigest()


def _sha(p):
    h=hashlib.sha256()
    with open(p,'rb') as f:
        for b in iter(lambda:f.read(8*1024**2),b''):h.update(b)
    return h.hexdigest()

def _write(p,obj):
    p=Path(p);p.parent.mkdir(parents=True,exist_ok=True);t=p.with_suffix(p.suffix+'.tmp')
    t.write_text(json.dumps(obj,indent=2,allow_nan=False),encoding='utf8');os.replace(t,p)


def _inspect(data):
    import h5py,numpy as np
    manifests={}
    for split,path in data.items():
        p=Path(path)
        if not p.is_file():raise FileNotFoundError(f'{split}: missing exact dataset path: {p}')
        rows={}
        with h5py.File(p,'r') as f:
            required=('pan','lms','ms','gt') if split in ('train','val','RR') else ('pan','lms','ms')
            if any(k not in f for k in required):raise ValueError(f'{split} missing keys {required}')
            n=len(f['pan']);h,w=f['pan'].shape[-2:]
            if f['pan'].shape!=(n,1,h,w) or f['lms'].shape!=(n,4,h,w) or f['ms'].shape!=(n,4,h//4,w//4):raise ValueError(f'{split}: unexpected NCHW or spatial ratio')
            if 'gt' in required and f['gt'].shape!=(n,4,h,w):raise ValueError(f'{split}: GT shape')
            if min(h,w)<16 or h%4 or w%4:raise ValueError(f'{split}: invalid spatial dimensions')
            for k in required:
                ds=f[k];lo=float('inf');hi=-float('inf')
                for start in range(0,n,256):
                    a=np.asarray(ds[start:start+256]);
                    if not np.isfinite(a).all():raise ValueError(f'{split}/{k}: nonfinite values')
                    lo=min(lo,float(a.min()));hi=max(hi,float(a.max()))
                # Cubic LMS ringing and tiny negative MS roundoff are valid. Never clip or min-max normalize.
                if max(abs(lo),abs(hi))>32768:raise ValueError(f'{split}/{k}: suspicious DN range {lo},{hi}')
                if k in ('pan','gt') and hi<=2:raise ValueError(f'{split}/{k}: expected raw DN values, not normalized data')
                rows[k]=dict(shape=list(ds.shape),dtype=str(ds.dtype),min=lo,max=hi)
                print(f'{split}/{k}: {lo:.8g} to {hi:.8g}; /2047 preserved',flush=True)
            expected={'train':17139,'val':1905,'RR':20,'FR':20}[split]
            if n!=expected:raise ValueError(f'{split}: expected {expected} samples, got {n}')
            if split in ('RR','FR') and n!=20:raise ValueError(f'{split}: expected 20 scenes, got {n}')
        manifests[split]=dict(path=str(p),sha256=_sha(p),keys=rows)
    if len({v['sha256'] for v in manifests.values()})!=4:raise ValueError('Duplicate split files')
    return manifests

def _plots(out):
    import matplotlib;matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    hist={a:json.loads((out/'results'/a/'history.json').read_text()) for a in ('N0','N1')}
    fig,axs=plt.subplots(1,4,figsize=(16,4))
    for a,rows in hist.items():
        for ax,key in zip(axs,('train_mse','val_mse','val_psnr','val_sam')):
            rr=[r for r in rows if r.get(key) is not None];ax.plot([r['epoch'] for r in rr],[r[key] for r in rr],label=a);ax.set_title(key);ax.grid(alpha=.2)
    axs[-1].legend();fig.tight_layout();fig.savefig(out/'curves.png',dpi=160);plt.close(fig)
    metrics={a:json.loads((out/'results'/a/'results/metrics.json').read_text()) for a in ('N0','N1')}
    fig,axs=plt.subplots(2,4,figsize=(16,8))
    deltas={}
    for ax,(proto,key) in zip(axs.flat,[('RR','PSNR'),('RR','SAM'),('RR','ERGAS'),('RR','SCC'),('RR','Q2n'),('FR','QNR'),('FR','D_lambda'),('FR','D_s')]):
        v=[metrics[a]['protocols'][proto]['mean'][key] for a in ('N0','N1')];ax.bar(['N0','N1'],v);ax.set_title(proto+' '+key+(' (provisional)' if proto=='FR' else ''));deltas[proto+'_'+key]=v[1]-v[0]
    fig.tight_layout();fig.savefig(out/'comparison.png',dpi=160);plt.close(fig)
    paired={}
    for proto in ('RR','FR'):
        r0=metrics['N0']['protocols'][proto]['rows'];r1=metrics['N1']['protocols'][proto]['rows']
        if len(r0)!=20 or len(r1)!=20:raise ValueError('Incomplete test')
        paired[proto]=[dict(index=x['index'],delta={k:y['metrics'][k]-x['metrics'][k] for k in x['metrics']}) for x,y in zip(r0,r1) if x['index']==y['index']]
        if len(paired[proto])!=20:raise ValueError('Scene alignment mismatch')
    _write(out/'paired_scene_deltas.json',paired)
    # Thresholds are preregistered screening targets, not statistical significance.
    v0=min(r['val_mse'] for r in hist['N0']);v1=min(r['val_mse'] for r in hist['N1'])
    d0=metrics['N0']['protocols']['FR']['mean'];d1=metrics['N1']['protocols']['FR']['mean']
    _write(out/'summary.json',dict(deltas=deltas,validation_screen_pass=v1<=v0*1.005,rr_screen_pass=deltas['RR_PSNR']>=-.03 and deltas['RR_SAM']<=.02,fr_screen_pass=deltas['FR_QNR']>=.003 and d1['D_lambda']<=d0['D_lambda'] and d1['D_s']<=d0['D_s'],status='single-seed exploratory comparison; no automatic baseline promotion',metrics=metrics))

def _verify_pair(out,cfg):
    arms=('N0','N1')
    initial=[json.loads((out/'results'/arm/'initialization.json').read_text()) for arm in arms]
    if initial[0]['state_sha256']!=initial[1]['state_sha256']:raise ValueError('Common initialization differs')
    histories=[json.loads((out/'results'/arm/'history.json').read_text()) for arm in arms]
    for history in histories:
        if [r['epoch'] for r in history]!=list(range(cfg['epochs']+1)):raise ValueError('Missing epoch records')
    orders=[[r['order_sha256'] for r in history[1:]] for history in histories]
    if orders[0]!=orders[1]:raise ValueError('Actual batch orders differ')
    skipped=[history[-1]['skipped'] for history in histories]
    if any(skipped):raise ValueError('AMP skipped updates found. Results preserved, comparison requires review: '+str(skipped))
    _write(out/'pair_verification.json',dict(initial_parameters_equal=True,actual_epoch_orders_equal=True,
            completed_epochs=cfg['epochs'],skipped_updates=skipped,bitwise_cuda_reproducibility_guaranteed=False))

def _training_plots(out):
    import matplotlib;matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    fig,axs=plt.subplots(1,4,figsize=(16,4))
    for arm in ('N0','N1'):
        rows=json.loads((out/'results'/arm/'history.json').read_text())
        for ax,key in zip(axs,('train_mse','val_mse','val_psnr','val_sam')):
            rr=[r for r in rows if r.get(key) is not None]
            ax.plot([r['epoch'] for r in rr],[r[key] for r in rr],label=arm)
            ax.set_title(key);ax.grid(alpha=.2)
    axs[-1].legend();fig.tight_layout();fig.savefig(out/'curves.png',dpi=160);plt.close(fig)

def _verify_artifacts(out,cfg):
    needed=['curves.png','comparison.png','pair_verification.json','paired_scene_deltas.json','summary.json','selection.json','data_manifest.json','config.json']
    for arm in ('N0','N1'):
        needed += [f'checkpoints/{arm}_QB_s{cfg["seed"]}/{name}.pt' for name in ('best','latest')]
        needed += [f'results/{arm}/{name}' for name in ('preflight.json','initialization.json','history.json','complete.json','results/metrics.json')]
        needed += [f'results/{arm}/results/RR_scene_{i:03}.png' for i in cfg['scenes']]
    for path in needed:
        if not (out/path).is_file() or (out/path).stat().st_size==0:raise ValueError('Missing artifact: '+path)
    for arm in ('N0','N1'):
        rec=json.loads((out/'results'/arm/'complete.json').read_text())
        ck=out/'checkpoints'/f'{arm}_QB_s{cfg["seed"]}'
        for name in ('best','latest'):
            if rec[name+'_sha256']!=_sha(ck/(name+'.pt')):raise ValueError('Checkpoint hash mismatch')
    _write(out/'artifact_verification.json',dict(required_files=needed,all_exist_nonempty=True,checkpoint_hashes_match=True,
           training_complete=True,evaluation_complete=True,remote_retention_verified=False))


def _archive(out,complete):
    items={}
    for p in sorted(out.rglob('*')):
        if p.is_file() and '__pycache__' not in p.parts and p.suffix!='.pyc' and p.name not in ('manifest.json','controller.lock') and p.suffix not in ('.tmp','.download') and p.name!='run.lock':items[str(p.relative_to(out))]=dict(bytes=p.stat().st_size,sha256=_sha(p))
    _write(out/'manifest.json',dict(files=items,state='complete' if complete else ('training_complete_evaluation_pending' if (out/'training_only.json').exists() else 'partial'),remote_retention_verified=False,checkpoint_resume_requires='both latest.pt and matching config/source/data'))
    zip_path=out.parent/(out.name+('_results.zip' if complete else ('_training.zip' if (out/'training_only.json').exists() else '_recovery.zip')))
    with zipfile.ZipFile(zip_path.with_suffix('.tmp'), 'w',compression=zipfile.ZIP_DEFLATED,compresslevel=1) as z:
        for rel in [*items,'manifest.json']:z.write(out/rel,arcname=out.name+'/'+rel)
    os.replace(zip_path.with_suffix('.tmp'),zip_path)
    with zipfile.ZipFile(zip_path) as z:
        bad=z.testzip()
        if bad:raise ValueError('ZIP CRC failed: '+bad)
        for rel,info in items.items():
            if hashlib.sha256(z.read(out.name+'/'+rel)).hexdigest()!=info['sha256']:raise ValueError('ZIP SHA256 mismatch: '+rel)
    zip_path.with_suffix('.zip.sha256').write_text(_sha(zip_path)+'  '+zip_path.name+'\n')
    print(('COMPLETE LOCAL OUTPUT: ' if complete else 'PARTIAL RECOVERY OUTPUT: ')+str(zip_path),flush=True)
    print('This confirms local output only. Verify Saved Version Output and download its ZIP before ending storage.',flush=True)
    try:
        from IPython.display import display,FileLink
        display(FileLink(str(zip_path)));display(FileLink(str(zip_path.with_suffix('.zip.sha256'))))
    except ImportError:pass

def main():
    import importlib.util
    missing=[name for name in ('torch','h5py','numpy','scipy','skimage','PIL','matplotlib') if importlib.util.find_spec(name) is None]
    if missing:raise RuntimeError('Missing dependencies: '+str(missing)+'; use a Kaggle GPU notebook image with these packages.')
    import torch
    if not RUN_ID.replace('_','').replace('-','').isalnum():raise ValueError('RUN_ID must be a plain folder name')
    if ('_s'+str(SEED)+'_') not in RUN_ID:raise ValueError('Update RUN_ID to match SEED')
    if MODE not in ('check','train'):raise ValueError('MODE must be check or train')
    if torch.cuda.device_count()!=2:raise RuntimeError('Select GPU T4 x2 before running; no CPU/single-GPU fallback.')
    if any('T4' not in torch.cuda.get_device_name(i) for i in range(2)):raise RuntimeError('This fixed run targets two T4 GPUs.')
    print('GPUs:',[torch.cuda.get_device_name(i) for i in range(2)],flush=True)
    out=Path('/kaggle/working')/RUN_ID
    import fcntl
    control_lock=Path('/kaggle/working')/(RUN_ID+'.controller.lock');lock=control_lock.open('a+b');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
    resume=bool(RESUME_FROM)
    if resume:
        old=Path(RESUME_FROM)
        if (old/'manifest.json').is_file():
            previous=json.loads((old/'manifest.json').read_text())
            for rel,info in previous['files'].items():
                path=old/rel
                if not path.is_file() or path.stat().st_size!=info['bytes'] or _sha(path)!=info['sha256']:raise ValueError('Saved Output integrity check failed: '+rel)
        if not (old/'config.json').exists():raise FileNotFoundError('RESUME_FROM must be the exact prior run folder containing config.json')
        if old.resolve()!=out.resolve():
            if out.exists():raise FileExistsError('Destination exists; choose exact same-session resume or a fresh RUN_ID')
            shutil.copytree(old,out)
    elif out.exists():raise FileExistsError(f'Existing run is protected: {out}. Set RESUME_FROM to resume or change RUN_ID for new work.')
    out.mkdir(parents=True,exist_ok=True)
    _write(out/'environment.json',dict(python=sys.version,torch=torch.__version__,cuda=torch.version.cuda,cudnn=torch.backends.cudnn.version(),platform=platform.platform(),gpus=[torch.cuda.get_device_name(i) for i in range(2)]))
    src=out/'provenance/source'
    for name,content in _BUNDLE.items():
        p=src/name;p.parent.mkdir(parents=True,exist_ok=True)
        if p.exists() and p.read_bytes()!=content.encode('utf8'):raise ValueError('Saved source differs; start a new run')
        p.write_bytes(content.encode('utf8'))
    data={k:str(Path(DATA_ROOT)/v) for k,v in dict(train='QuickBird__Training_Dataset__train_qb.h5',val='QuickBird__Training_Dataset__valid_qb.h5',RR='QuickBird__Testing_Dataset_ReducedData_H5_Format__test_qb_multiExm1.h5',FR='QuickBird__Testing_Dataset_FullData_H5_Format__test_qb_OrigScale_multiExm1.h5').items()}
    manifests=_inspect(data);_write(out/'data_manifest.json',manifests)
    executed,source_capture=_executed_source()
    controller_hash=_controller_fingerprint(executed)
    cfg=dict(controller_sha256=controller_hash,out=str(out),data=data,seed=SEED,epochs=100,batch=64,micro=32,lr=1e-4,std_floor=0.01,
             mode=MODE,resume=resume,gpu_map={'N0':0,'N1':1},scenes=[1,8,11,13,19],
             evaluate_after_training=EVALUATE_AFTER_TRAINING,
             source_commit='2878e9bbf273edaeafd2b1251a8aed0227f06a19',
             source_hashes={k:hashlib.sha256(v.encode()).hexdigest() for k,v in _BUNDLE.items()},
             precision='AMP FP16 train; FP32 stats/inverse/loss/validation/test; TF32 off',
             selection='minimum validation MSE including epoch0; earliest exact tie',
             experiment=33,research_track='performance',experimenter='김경찬',
             model='fresh original RestoredPansharpeningNet K4; N1 shared per-sample MS affine wrapper',
             data_normalization='DN/2047; no clipping; GT excluded from input statistics')
    stable={k:v for k,v in cfg.items() if k not in ('out','resume','data','mode','evaluate_after_training')};stable['data_hashes']={k:v['sha256'] for k,v in manifests.items()}
    cfg['fingerprint']=hashlib.sha256(json.dumps(stable,sort_keys=True).encode()).hexdigest()
    cp=out/'config.json'
    if resume and json.loads(cp.read_text())['fingerprint']!=cfg['fingerprint']:raise ValueError('Resume incompatible with source/config/data')
    for arm in ('N0','N1'):
        folder=out/'results'/arm
        for name in ('failure.json','complete.json','training_complete.json'):
            marker=folder/name
            if marker.exists():marker.unlink()
    if (out/'training_only.json').exists():(out/'training_only.json').unlink()
    (out/'provenance'/'run_cell.py').write_text(executed,encoding='utf8')
    _write(out/'provenance'/'controller_capture.json',dict(method=source_capture,canonical_sha256=controller_hash,raw_sha256=hashlib.sha256(executed.encode()).hexdigest()))
    _write(cp,cfg);_write(out/'selection.json',dict(seed=SEED,indices=cfg['scenes'],index_base=0,unit='full RR scene',rule='fixed before training/test scoring',display_order=cfg['scenes'],panels=['LR MS nearest','PAN','prediction','GT'],rgb_bands=[2,1,0],contrast='per-scene GT 1st/99th percentile shared across MS panels',FR_has_GT=False))
    _write(out/'protocol.json',dict(experiment=33,RR='20 full scenes, peak2047 per-band PSNR averaged per scene',FR='20 full scenes; QNR/D_lambda/D_s provisional',std='population variance over C,H,W of LR MS per sample, floor=0.01',loss='MSE after inverse in DN/2047 units',predefined_targets=dict(RR_PSNR_min_delta=-.03,RR_SAM_max_delta=.02,FR_QNR_min_delta=.003),test_tuning=False))
    handles=[];complete=False
    try:
        for arm,gpu in cfg['gpu_map'].items():
            env=dict(os.environ,CUDA_VISIBLE_DEVICES=str(gpu),CUBLAS_WORKSPACE_CONFIG=':4096:8',PYTHONUNBUFFERED='1')
            f=(out/'results'/arm/'worker.log');f.parent.mkdir(parents=True,exist_ok=True);stream=f.open('a',encoding='utf8')
            proc=subprocess.Popen([sys.executable,'-u',str(src/'worker.py'),str(cp),arm],env=env,stdout=stream,stderr=subprocess.STDOUT);handles.append((arm,proc,stream))
        last={};initial_pair_checked=False
        while any(p.poll() is None for _,p,_ in handles):
            for arm,p,f in handles:
                status=out/'results'/arm/'status.json'
                if status.exists():
                    s=status.read_text()
                    if s!=last.get(arm):print(s,flush=True);last[arm]=s
            initial_files=[out/'results'/a/'initialization.json' for a in ('N0','N1')]
            if not initial_pair_checked and all(p.exists() for p in initial_files):
                initial_pair_checked=True
                if len({json.loads(p.read_text())['state_sha256'] for p in initial_files})!=1:raise ValueError('Common initialization differs; stopping both workers')
            # Fail promptly and request a safe checkpoint from a surviving peer.
            if any(p.poll() is not None and p.returncode!=0 for _,p,_ in handles):
                for _,p,_ in handles:
                    if p.poll() is None:p.terminate()
                break
            time.sleep(5)
        for arm,p,f in handles:
            rc=p.wait();f.close()
            if rc:
                print((out/'results'/arm/'worker.log').read_text()[-12000:],flush=True)
                raise RuntimeError(f'{arm} failed, exit {rc}; see results/{arm}/worker.log')
        if MODE=='check':
            print('CHECK PASS: two GPU-resident caches, common fresh initialization, finite forward/backward; training not started.',flush=True);return
        if not EVALUATE_AFTER_TRAINING:
            for arm in ('N0','N1'):
                if not (out/'results'/arm/'training_complete.json').is_file():raise RuntimeError('Training interrupted; resume required')
            _verify_pair(out,cfg)
            _training_plots(out)
            _write(out/'training_only.json',dict(state='training_complete_evaluation_pending',test_scored=False))
            print('TRAINING COMPLETE; RR/FR intentionally not scored. Inspect validation before further experiments.',flush=True)
            return
        for arm in ('N0','N1'):
            if not (out/'results'/arm/'complete.json').exists():raise RuntimeError(f'{arm} stopped safely before completion; resume required')
        init=[json.loads((out/'results'/a/'initialization.json').read_text()) for a in ('N0','N1')]
        if init[0]['state_sha256']!=init[1]['state_sha256']:raise ValueError('Initial states differ')
        hs=[json.loads((out/'results'/a/'history.json').read_text())[1:] for a in ('N0','N1')]
        if [r['order_sha256'] for r in hs[0]]!=[r['order_sha256'] for r in hs[1]]:raise ValueError('Actual epoch orders differ')
        for a in ('N0','N1'):
            for i in cfg['scenes']:
                if not (out/'results'/a/'results'/f'RR_scene_{i:03}.png').is_file():raise ValueError('Missing selected preview')
        _verify_pair(out,cfg);_plots(out);_verify_artifacts(out,cfg);complete=True
    finally:
        for _,p,f in handles:
            if p.poll() is None:p.terminate()
        for _,p,f in handles:
            try:p.wait(timeout=60)
            except subprocess.TimeoutExpired:p.kill();p.wait()
            if not f.closed:f.close()
        _archive(out,complete)

if __name__ == '__main__':
    main()